1	/**
2	 * GV-2: the published contract of the audit bundle: the manifest a bundle carries (`manifest.json`), the detached
3	 * signature envelope (`manifest.sig.json`), the JSON document a verification prints, the process exit codes and the
4	 * limits a bundle must stay within. The published schemas (docs/protocol/audit-bundle-v1.schema.json and
5	 * audit-verify-result-v1.schema.json) are generated from the types here by scripts/gen_audit_schema.mjs, so they are
6	 * plain data (no functions, no index signatures); test/audit_schema.test.ts fails when either falls behind.
7	 *
8	 * The code that writes and checks a bundle is core/audit_bundle.ts.
9	 */
10	import type { ChainLink, ChainVerdict } from "./core/hash_chain.js";
11	
12	/**
13	 * Version of `manifest.json` and `manifest.sig.json`. Adding an optional member keeps the version; removing or renaming
14	 * a member, or changing a member's type or meaning, bumps it. Every change is recorded in
15	 * docs/protocol/AUDIT_BUNDLE_VERSIONS.json.
16	 */
17	export const AUDIT_BUNDLE_SCHEMA_VERSION = 1;
18	/** Version of the document a verification prints, under the same rule; ledger docs/protocol/AUDIT_VERIFY_RESULT_VERSIONS.json. */
19	export const AUDIT_VERIFY_RESULT_SCHEMA_VERSION = 1;
20	
21	export const AUDIT_BUNDLE_FORMAT = "nexus-audit-bundle/1";
22	export const AUDIT_MANIFEST_FILE = "manifest.json";
23	export const AUDIT_SIGNATURE_FILE = "manifest.sig.json";
24	/** Prefix of the signed bytes (the prefix, then the exact bytes of manifest.json), so a signature made here cannot be taken for one over anything else. */
25	export const AUDIT_SIGNATURE_DOMAIN = "nexus-audit-bundle-signature/1\n";
26	
27	/** What a bundle must stay within. The writer refuses to produce a bundle outside these; the verifier reports one as a finding instead of reading on. */
28	export const AUDIT_LIMITS = {
29	  /** Largest manifest.json, in bytes. */
30	  manifestBytes: 4 * 1024 * 1024,
31	  /** Most payload files in a bundle. */
32	  files: 10_000,
33	  /** Largest payload file, in bytes. */
34	  fileBytes: 256 * 1024 * 1024,
35	  /** Largest sum of payload file sizes, in bytes. */
36	  totalBytes: 2 * 1024 * 1024 * 1024,
37	  /** Most records in one chained log. */
38	  logRecords: 1_000_000,
39	  /** Longest line of a chained log, in bytes. */
40	  logLineBytes: 4 * 1024 * 1024,
41	  /** Deepest nesting of arrays and objects in the manifest and in a chained-log record. */
42	  jsonDepth: 64,
43	  /** Most path segments of a payload file (`evidence/diffs/a.diff` has 3). */
44	  pathDepth: 4,
45	  /** Longest path segment, in characters. */
46	  pathSegmentChars: 160,
47	  /** Most findings a verification lists; the total is still counted. */
48	  findings: 100,
49	} as const;
50	
51	/** What a payload file is. */
52	export const AUDIT_FILE_ROLES = [
53	  "session_export",
54	  "session_export_markdown",
55	  "validation_receipts",
56	  "last_turn",
57	  "verify_receipt",
58	  "verification_attempts",
59	  "verification_config_attempts",
60	  "evidence_provenance",
61	  "evidence_findings",
62	  "diff",
63	  "flight_log",
64	  "trace",
65	] as const;
66	export type AuditFileRole = (typeof AUDIT_FILE_ROLES)[number];
67	
68	/** The last link of a chain: the position of the last record and its hash. */
69	export interface AuditChainHead {
70	  seq: number;
71	  hash: string;
72	}
73	
74	/** One payload file of the bundle. */
75	export interface AuditFileEntry {
76	  /** Relative POSIX path inside the bundle: segments of `[A-Za-z0-9._-]`, never `.` or `..`. */
77	  path: string;
78	  /** Size of the file in bytes. */
79	  bytes: number;
80	  /** SHA-256 of the file's bytes, lowercase hex. */
81	  sha256: string;
82	  role: AuditFileRole;
83	  /** Link to the entry before this one (core/hash_chain.ts `linkRecord` over `{ path, bytes, sha256, role }`). */
84	  chain: ChainLink;
85	}
86	
87	export const AUDIT_CHAINED_LOG_KINDS = ["flight", "verification_config_attempts"] as const;
88	export type AuditChainedLogKind = (typeof AUDIT_CHAINED_LOG_KINDS)[number];
89	
90	/** The log a bundled excerpt was taken from, as it was when the bundle was written. */
91	export interface AuditChainedLogSource {
92	  records: number;
93	  head?: AuditChainHead;
94	  closed: boolean;
95	  bytes: number;
96	  sha256: string;
97	  /** The bundle holds the whole source log; false when it holds a prefix of it. */
98	  complete: boolean;
99	}
100	
101	/** A payload file that is itself a hash-chained log (one JSON record per line), with what its chain read as at export. */
102	export interface AuditChainedLog {
103	  /** The log's path in the bundle; it is also listed in `files`. */
104	  path: string;
105	  kind: AuditChainedLogKind;
106	  /** Number of records in the bundled log. */
107	  records: number;
108	  /** What `verifyChain` reported for the bundled log at export. A log already broken or unchained is recorded as such, not hidden. */
109	  status: ChainVerdict["status"];
110	  /** The last record's link; present when the chain was intact and not empty. */
111	  head?: AuditChainHead;
112	  /** The log ended with its defined last record (a flight's `session_end`). False: still recording, stopped early, or cut. */
113	  closed?: boolean;
114	  source?: AuditChainedLogSource;
115	  /** How the log was chosen: named by the operator, or found by time window (a heuristic that can pick up another task's log). */
116	  selection?: "explicit" | "time_window";
117	}
118	
119	/** An artefact that was left out, and why. */
120	export interface AuditOmitted {
121	  artefact: string;
122	  reason: string;
123	}
124	
125	/** The Nexus build that wrote the bundle. */
126	export interface AuditBuildIdentity {
127	  version: string;
128	  commit: string;
129	  dirty: boolean;
130	}
131	
132	/** What the bundle is about. */
133	export interface AuditSubject {
134	  kind: "task" | "session";
135	  task_id: string | null;
136	  session_id: string | null;
137	  /** The store the subject was read from. */
138	  store: "tasks" | "sessions";
139	  workspace_path: string | null;
140	  /** SHA-256 (hex) of the workspace path, so bundles of one workspace can be matched when the path is withheld. */
141	  workspace_sha256: string | null;
142	  status: string | null;
143	  updated_at: string | null;
144	  /** False when the subject could still be changing while it was exported. */
145	  at_rest: boolean;
146	}
147	
148	export type AuditRedaction = "standard" | "strict";
149	
150	/**
151	 * `manifest.json`. On disk it is exactly `canonicalJson(manifest) + "\n"` (core/hash_chain.ts: keys sorted at every
152	 * depth, no whitespace), UTF-8; any other byte form is rejected, so the SHA-256 of the file is well defined.
153	 */
154	export interface AuditManifest {
155	  schema_version: typeof AUDIT_BUNDLE_SCHEMA_VERSION;
156	  format: typeof AUDIT_BUNDLE_FORMAT;
157	  /** 32 lowercase hex characters, random per bundle. */
158	  bundle_id: string;
159	  /** When the bundle was written (ISO 8601, UTC). */
160	  created_at: string;
161	  nexus: AuditBuildIdentity;
162	  subject: AuditSubject;
163	  redaction: AuditRedaction;
164	  /** Every payload file, sorted by path, each linked to the one before it. `manifest.json` and `manifest.sig.json` are not listed. */
165	  files: AuditFileEntry[];
166	  /** The link of the last entry of `files`; null when there are none. */
167	  files_head: AuditChainHead | null;
168	  chained_logs: AuditChainedLog[];
169	  omitted: AuditOmitted[];
170	  /** SHA-256 (hex) of `canonicalJson` of this manifest without `root_sha256`, as UTF-8. */
171	  root_sha256: string;
172	}
173	
174	/**
175	 * `manifest.sig.json`, the detached signature. The signed bytes are AUDIT_SIGNATURE_DOMAIN followed by the exact bytes
176	 * of manifest.json. The public key is never in the bundle: a verifier checks against a key it already holds, and
177	 * `public_key_sha256` only helps name the key in messages.
178	 */
179	export interface AuditSignatureEnvelope {
180	  schema_version: typeof AUDIT_BUNDLE_SCHEMA_VERSION;
181	  algorithm: "ed25519";
182	  signed_file: typeof AUDIT_MANIFEST_FILE;
183	  /** SHA-256 (hex) of the bytes of manifest.json. */
184	  manifest_sha256: string;
185	  /** SHA-256 (hex) of the signing key's public half, as SPKI DER. */
186	  public_key_sha256: string;
187	  /** The ed25519 signature, base64. */
188	  signature: string;
189	}
190	
191	/** A document of the bundle: the manifest, or the signature envelope. */
192	export type AuditBundleDocument = AuditManifest | AuditSignatureEnvelope;
193	
194	export type AuditFindingKind =
195	  /** The signature does not verify against the key supplied. */
196	  | "signature_invalid"
197	  /** The envelope names a different key than the one supplied. */
198	  | "signature_key_mismatch"
199	  /** A key was supplied and the bundle carries no signature. */
200	  | "signature_missing"
201	  /** A file's bytes are not the ones the manifest records. */
202	  | "file_altered"
203	  /** A file the manifest lists is not in the bundle. */
204	  | "file_missing"
205	  /** The bundle holds a file or directory the manifest does not list. */
206	  | "file_unexpected"
207	  /** A symbolic link, or something that is not a regular file or directory. It was not read. */
208	  | "unsafe_entry"
209	  /** An entry could not be read, so it was not checked. */
210	  | "unreadable_entry"
211	  /** There is no manifest.json. */
212	  | "manifest_missing"
213	  /** The manifest is not valid JSON, or not a manifest: a member is missing, of the wrong type or breaks a rule. */
214	  | "manifest_malformed"
215	  /** The manifest parses, but its bytes are not the canonical form. */
216	  | "manifest_not_canonical"
217	  /** The manifest's content does not hash to its `root_sha256`. */
218	  | "manifest_root_mismatch"
219	  /** The file entries do not form an intact hash chain ending at `files_head`. */
220	  | "manifest_chain_broken"
221	  /** The manifest's SHA-256 is not the one the caller expected. */
222	  | "manifest_sha256_mismatch"
223	  /** A chained log is consistent in itself but does not end where the manifest recorded: records are missing from the end, or the log was replaced. */
224	  | "log_head_mismatch"
225	  /** A chained log the manifest recorded as intact no longer is. */
226	  | "log_chain_broken"
227	  /** A limit of AUDIT_LIMITS was exceeded; what lies beyond it was not checked. */
228	  | "limit_exceeded"
229	  /** The bundle declares a schema version this Nexus does not read. Nothing was checked. */
230	  | "unsupported_version";
231	
232	export interface AuditFinding {
233	  kind: AuditFindingKind;
234	  /** The path inside the bundle the finding is about (characters outside printable ASCII escaped); absent for a finding about the bundle as a whole. */
235	  path?: string;
236	  /** One sentence a person can read. */
237	  message: string;
238	  /** For `file_altered`: what the manifest records and what was found. */
239	  expected_sha256?: string;
240	  found_sha256?: string;
241	  expected_bytes?: number;
242	  found_bytes?: number;
243	}
244	
245	/**
246	 * intact_signed: every check passed and the signature verifies against the caller's key. intact_unsigned: every check
247	 * passed and there is no signature, so the result rests on the manifest alone. signature_unchecked: every file check
248	 * passed, and a signature is present that was not checked. tampered: at least one finding. unsupported_version: nothing
249	 * was checked.
250	 */
251	export type AuditVerifyResultName = "intact_signed" | "intact_unsigned" | "signature_unchecked" | "tampered" | "unsupported_version";
252	
253	/** absent: no manifest.sig.json. unchecked: present, not checked. valid, invalid: checked against the caller's key. missing: a key was supplied and there is no signature. */
254	export type AuditSignatureStatus = "absent" | "unchecked" | "valid" | "invalid" | "missing";
255	
256	/** A chained log as the verification read it. */
257	export interface AuditVerifiedLog {
258	  path: string;
259	  kind: AuditChainedLogKind;
260	  /** What `verifyChain` reports for the log now; `not_checked` when the log could not be read as one. */
261	  status: ChainVerdict["status"] | "not_checked";
262	  records: number;
263	  /** The log reads exactly as the manifest recorded it (status, record count, head). */
264	  matches_manifest: boolean;
265	}
266	
267	/** Printed when the bundle was examined, whatever the outcome. */
268	export interface AuditVerifyResult {
269	  /** Version of this document's schema. Always the first member. */
270	  schema_version: typeof AUDIT_VERIFY_RESULT_SCHEMA_VERSION;
271	  result: AuditVerifyResultName;
272	  /** The process exit code (AUDIT_EXIT_CODES). */
273	  exitCode: number;
274	  /** From the manifest; null when it could not be read. An unsigned manifest's own statements are not evidence of who wrote it. */
275	  bundle_id: string | null;
276	  /** SHA-256 (hex) of the bytes of manifest.json as found; null when it could not be read. The value to compare with one recorded at export. */
277	  manifest_sha256: string | null;
278	  /** The manifest hash the caller expected, when one was given. A mismatch is a `manifest_sha256_mismatch` finding. */
279	  expected_manifest_sha256: string | null;
280	  signature: AuditSignatureStatus;
281	  /** SHA-256 (hex) of the public key the signature was checked against; null when none was. */
282	  public_key_sha256: string | null;
283	  files: {
284	    /** Files the manifest lists. */
285	    listed: number;
286	    /** Of those, the files whose bytes and SHA-256 match. */
287	    matched: number;
288	  };
289	  chained_logs: AuditVerifiedLog[];
290	  /** At most AUDIT_LIMITS.findings entries; `findings_total` counts them all. */
291	  findings: AuditFinding[];
292	  findings_total: number;
293	  /** Things worth knowing that are not failures: a log that was not closed at export, a bounded excerpt. */
294	  notes: string[];
295	}
296	
297	/** Printed instead of a result when the verification could not be carried out (no such directory, an invalid option, an internal error). Nothing was established. */
298	export interface AuditVerifyError {
299	  /** Version of this document's schema. Always the first member. */
300	  schema_version: typeof AUDIT_VERIFY_RESULT_SCHEMA_VERSION;
301	  error: string;
302	  exitCode: number;
303	}
304	
305	/** The one JSON document a verification prints. A result has `result`; an error document does not. */
306	export type AuditVerifyOutput = AuditVerifyResult | AuditVerifyError;
307	
308	export interface AuditExitCode {
309	  code: number;
310	  name: string;
311	  when: string;
312	}
313	
314	/**
315	 * Every exit code of `nexus audit export` and `nexus audit verify`, one row per condition (the same row shape as
316	 * RUN_EXIT_CODES and VERIFY_EXIT_CODES). A code can appear in several rows: the exit code alone does not tell those
317	 * conditions apart, the JSON document does. Only 0 means a bundle was written or found intact.
318	 */
319	export const AUDIT_EXIT_CODES = [
320	  { code: 0, name: "exported", when: "`audit export`: the bundle was written." },
321	  { code: 0, name: "intact_signed", when: "`audit verify`: every file matches the manifest, and the manifest is signed by the key given with `--public-key`." },
322	  { code: 0, name: "intact_unsigned", when: "`audit verify`: every file matches the manifest and the bundle is not signed. The result rests on the manifest alone, and the output says so every time." },
323	  { code: 1, name: "tampered", when: "`audit verify`: a file is altered, missing, extra or unsafe (a symbolic link, not a regular file); the manifest is malformed or inconsistent; a chained log does not match its recorded head; a limit was exceeded; the signature is invalid; or a key was given and the bundle has no signature." },
324	  { code: 1, name: "error", when: "The command itself failed (the bundle directory cannot be read, an export could not be written), so nothing was established." },
325	  { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs; no JSON document)." },
326	  { code: 2, name: "signature_unchecked", when: "`audit verify`: every file matches the manifest, and the bundle carries a signature that was not checked because no `--public-key` was given." },
327	  { code: 2, name: "unsupported_version", when: "`audit verify`: the bundle declares a schema version this Nexus does not read. Nothing was checked." },
328	  { code: 2, name: "usage", when: "A usage error: an invalid option value or combination, or an unknown `audit` subcommand." },
329	  { code: 2, name: "subject_not_found", when: "`audit export`: no task or session has the given id." },
330	  { code: 130, name: "interrupted", when: "Interrupted (SIGINT)." },
331	] as const satisfies readonly AuditExitCode[];
332	
333	export type AuditExitName = (typeof AUDIT_EXIT_CODES)[number]["name"];
334	
335	export function auditExitCode(name: AuditExitName): number {
336	  return AUDIT_EXIT_CODES.find((row) => row.name === name)!.code;
337	}
338

