312	/** `root_sha256` of a manifest: SHA-256 of the canonical JSON of everything else in it. */
313	function manifestRoot(manifest: Record<string, unknown>): string {
314	  const { root_sha256: _root, ...body } = manifest;
315	  return sha256Hex(canonicalJson(body));
316	}
