429	function writePrivateFile(file: string, bytes: Uint8Array, durable: boolean): void {
430	  const fd = fs.openSync(file, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, 0o600);
431	  try {
432	    fs.writeFileSync(fd, bytes);
433	    fs.fchmodSync(fd, 0o600);
434	    if (durable) fs.fsyncSync(fd);
435	  } finally {
436	    fs.closeSync(fd);
437	  }
438	}
439	
440	function makePrivateDir(dir: string): void {
441	  fs.mkdirSync(dir, { mode: 0o700 });
442	  fs.chmodSync(dir, 0o700);
443	}
444	
445	/**
446	 * Writes the bundle directory `options.out` from artefacts held in memory: every file 0600, every directory 0700,
447	 * manifest.json last and exactly `canonicalJson(manifest) + "\n"`. Each artefact is hashed and written from the same
448	 * buffer. The bundle is built beside its destination as `<out>.partial-<random>` and renamed into place, so `out`
449	 * either does not exist or is complete; on any failure the partial directory is removed and AuditBundleError is thrown.
450	 * The destination name is created exclusively just before the rename, so an entry that appeared there after the first
451	 * check (even an empty directory) makes the write fail instead of being replaced.
452	 * Unsigned: see the header of this file for what that does and does not establish.
453	 */
454	export function writeAuditBundle(input: AuditBundleInput, options: WriteAuditBundleOptions): WrittenAuditBundle {
455	  const out = path.resolve(options.out);
456	  const manifest = buildAuditManifest(input, options);
457	  const manifestBytes = auditManifestBytes(manifest);
458	  if (fs.lstatSync(out, { throwIfNoEntry: false })) throw new AuditBundleError(`${out} already exists; an audit bundle is never written over anything`);
459	  const partial = `${out}.partial-${randomBytes(8).toString("hex")}`;
460	  const durable = options.durable !== false;
461	  let created = false;
462	  let reserved = false;
463	  try {
464	    makePrivateDir(partial);
465	    created = true;
466	    const made = new Set<string>();
467	    for (const artefact of input.artefacts) {
468	      const segments = artefact.path.split("/");
469	      for (let i = 1; i < segments.length; i++) {
470	        const dir = segments.slice(0, i).join("/");
471	        if (made.has(dir)) continue;
472	        makePrivateDir(path.join(partial, ...dir.split("/")));
473	        made.add(dir);
474	      }
475	      writePrivateFile(path.join(partial, ...segments), artefact.bytes, durable);
476	    }
477	    writePrivateFile(path.join(partial, AUDIT_MANIFEST_FILE), manifestBytes, durable);
478	    if (durable) {
479	      for (const dir of made) fsyncDirectoryDurably(path.join(partial, ...dir.split("/")));
480	      fsyncDirectoryDurably(partial);
481	    }
482	    // Node has no rename that refuses to replace. Creating the name first fails on anything already there; the rename
483	    // then replaces only that empty directory, and fails if something was put inside it meanwhile.
484	    fs.mkdirSync(out, { mode: 0o700 });
485	    reserved = true;
486	    fs.renameSync(partial, out);
487	    reserved = false;
488	    if (durable) fsyncDirectoryDurably(path.dirname(out));
489	  } catch (err) {
490	    if (created) fs.rmSync(partial, { recursive: true, force: true });
491	    if (reserved) {
492	      try {
493	        fs.rmdirSync(out);
494	      } catch {
495	        // Not empty: someone else's content now; it is not ours to remove.
496	      }
497	    }
498	    throw new AuditBundleError(`the audit bundle was not written: ${err instanceof Error ? err.message : String(err)}`);
499	  }
500	  return { dir: out, manifest, manifestSha256: sha256Hex(manifestBytes) };
501	}
