519	class Findings {
520	  readonly listed: AuditFinding[] = [];
521	  total = 0;
522	  constructor(private readonly cap: number) {}
523	  add(kind: AuditFindingKind, message: string, at?: string, detail: Partial<AuditFinding> = {}): void {
524	    this.total++;
525	    if (this.listed.length < this.cap) this.listed.push({ kind, ...(at === undefined ? {} : { path: shown(at) }), message, ...detail });
