528	
529	const errorCode = (err: unknown): string => (err && typeof (err as { code?: unknown }).code === "string" ? (err as { code: string }).code : err instanceof Error ? err.name : "error");
530	
531	function verifyError(exit: "error" | "usage", error: string): AuditVerification {
532	  return { document: { schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, error, exitCode: auditExitCode(exit) }, exit };
533	}
