535	/**
536	 * Opens a file found in the bundle's tree for reading, refusing a symbolic link (O_NOFOLLOW) and anything that is not a
537	 * regular file (`fstat` on the descriptor, so the check is of what was opened). O_NONBLOCK keeps a FIFO swapped in
538	 * after the listing from blocking the open. Returns the descriptor and size, or the finding.
539	 */
540	function openRegular(full: string): { fd: number; size: number } | { kind: AuditFindingKind; message: string } {
541	  let fd: number;
542	  try {
543	    fd = fs.openSync(full, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
544	  } catch (err) {
545	    const code = errorCode(err);
546	    if (code === "ELOOP" || code === "EMLINK") return { kind: "unsafe_entry", message: "a symbolic link; it was not followed or read" };
547	    return { kind: "unreadable_entry", message: `could not be opened (${code}); it was not checked` };
548	  }
549	  try {
550	    const stat = fs.fstatSync(fd);
551	    if (stat.isFile()) return { fd, size: stat.size };
552	  } catch (err) {
553	    fs.closeSync(fd);
554	    return { kind: "unreadable_entry", message: `could not be examined (${errorCode(err)}); it was not checked` };
555	  }
556	  fs.closeSync(fd);
557	  return { kind: "unsafe_entry", message: "not a regular file; it was not read" };
558	}
559	
560	/** Reads an open file to its end in pieces, at most `max` bytes. Returns the byte count, or undefined when it holds more. */
561	function readStream(fd: number, max: number, each: (chunk: Buffer) => void): number | undefined {
562	  const buffer = Buffer.allocUnsafe(READ_CHUNK);
563	  let bytes = 0;
564	  for (;;) {
565	    const n = fs.readSync(fd, buffer, 0, READ_CHUNK, null);
566	    if (n === 0) return bytes;
567	    bytes += n;
568	    if (bytes > max) return undefined;
569	    each(buffer.subarray(0, n));
570	  }
571	}
572	
573	function effectiveLimits(given: Partial<AuditLimits> | undefined): AuditLimits {
574	  const limits: AuditLimits = { ...AUDIT_LIMITS };
575	  for (const key of Object.keys(limits) as Array<keyof AuditLimits>) {
576	    const value = given?.[key];
577	    if (typeof value === "number" && Number.isSafeInteger(value) && value >= 0 && value < limits[key]) limits[key] = value;
578	  }
579	  return limits;
580	}
581	
582	/**
583	 * Checks the bundle directory against its manifest and returns the result document with its exit-code row. It does not
584	 * throw for a bad bundle: whatever is wrong is a finding (every one is counted, the first AUDIT_LIMITS.findings are
585	 * listed), and what could not be done at all is an error document. An intact result is returned only when every listed
586	 * file was read and matched and every chained log reads as recorded.
587	 */
588	export function verifyAuditBundle(bundleDir: string, options: VerifyAuditBundleOptions = {}): AuditVerification {
589	  try {
590	    return verify(bundleDir, options);
591	  } catch (err) {
592	    return verifyError("error", `the verification failed and established nothing (${shown(err instanceof Error ? `${err.name}: ${err.message}` : String(err))})`);
593	  }
594	}
595	
596	function verify(bundleDir: string, options: VerifyAuditBundleOptions): AuditVerification {
597	  // A caller that passes an option this version does not have (a public key, before signing exists) must not be told
598	  // "intact" as if the option had been honoured.
599	  for (const key of Object.keys(options)) {
600	    if (key !== "expectManifestSha256" && key !== "limits") return verifyError("usage", `unsupported verification option: ${shown(key)}`);
601	  }
602	  let expected: string | null = null;
603	  if (options.expectManifestSha256 !== undefined) {
604	    expected = String(options.expectManifestSha256).toLowerCase();
605	    if (!HEX64.test(expected)) return verifyError("usage", "the expected manifest hash is not a SHA-256 (64 hex characters)");
606	  }
607	  const limits = effectiveLimits(options.limits);
608	  const root = path.resolve(bundleDir);
609	  let rootStat: fs.Stats | undefined;
610	  try {
611	    rootStat = fs.statSync(root, { throwIfNoEntry: false });
612	  } catch (err) {
613	    return verifyError("error", `the bundle directory cannot be read (${errorCode(err)})`);
614	  }
615	  if (!rootStat) return verifyError("error", "there is no bundle directory at that path");
616	  if (!rootStat.isDirectory()) return verifyError("error", "an audit bundle is a directory; that path is not one");
617	
618	  const findings = new Findings(limits.findings);
619	  const notes: string[] = [];
620	  const logs: AuditVerifiedLog[] = [];
621	  let signature: AuditSignatureStatus = "absent";
622	  let manifestSha256: string | null = null;
623	  let bundleId: string | null = null;
624	  let listed = 0;
625	  let matched = 0;
626	  let unsupported = false;
627	
628	  // Signing arrives in slice 3. Here a signature file is only noticed, so that a signed bundle is never reported as
629	  // plainly intact by a verifier that did not check the signature.
630	  try {
631	    const stat = fs.lstatSync(path.join(root, AUDIT_SIGNATURE_FILE), { throwIfNoEntry: false });
632	    if (stat) {
633	      signature = "unchecked";
634	      if (!stat.isFile()) findings.add("unsafe_entry", stat.isSymbolicLink() ? "a symbolic link; it was not followed or read" : "not a regular file; it was not read", AUDIT_SIGNATURE_FILE);
635	    }
636	  } catch (err) {
637	    signature = "unchecked";
638	    findings.add("unreadable_entry", `could not be examined (${errorCode(err)}); it was not checked`, AUDIT_SIGNATURE_FILE);
639	  }
640	
641	  const manifest = readManifest();
642	  if (manifest && !unsupported) checkTree(manifest);
643	
644	  const result: AuditVerifyResultName = unsupported ? "unsupported_version" : findings.total > 0 ? "tampered" : signature === "unchecked" ? "signature_unchecked" : "intact_unsigned";
645	  if (result !== "tampered" && result !== "unsupported_version" && (!manifest || matched !== listed || logs.some((log) => !log.matches_manifest))) {
646	    throw new Error("internal inconsistency: no finding, but not every file and log was checked");
647	  }
648	  const document: AuditVerifyResult = {
649	    schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION,
650	    result,
651	    exitCode: auditExitCode(result),
652	    bundle_id: bundleId,
653	    manifest_sha256: manifestSha256,
654	    expected_manifest_sha256: expected,
655	    signature,
656	    public_key_sha256: null,
657	    files: { listed, matched },
658	    chained_logs: logs,
659	    findings: findings.listed,
660	    findings_total: findings.total,
661	    notes,
662	  };
663	  return { document, exit: result };
664	
665	  /** manifest.json, read and checked as a document. Undefined when what follows cannot be checked against it. */
666	  function readManifest(): AuditManifest | undefined {
667	    const full = path.join(root, AUDIT_MANIFEST_FILE);
668	    let stat: fs.Stats | undefined;
669	    try {
670	      stat = fs.lstatSync(full, { throwIfNoEntry: false });
671	    } catch (err) {
672	      findings.add("unreadable_entry", `could not be examined (${errorCode(err)}); nothing could be checked against it`, AUDIT_MANIFEST_FILE);
673	      return undefined;
674	    }
675	    if (!stat) {
676	      findings.add("manifest_missing", "the bundle has no manifest.json, so nothing in it can be checked");
677	      return undefined;
678	    }
679	    if (!stat.isFile()) {
680	      findings.add("unsafe_entry", stat.isSymbolicLink() ? "a symbolic link; it was not followed or read" : "not a regular file; it was not read", AUDIT_MANIFEST_FILE);
681	      return undefined;
682	    }
683	    const opened = openRegular(full);
684	    if (!("fd" in opened)) {
685	      findings.add(opened.kind, opened.message, AUDIT_MANIFEST_FILE);
686	      return undefined;
687	    }
688	    const chunks: Buffer[] = [];
689	    let size: number | undefined;
690	    try {
691	      size = opened.size > limits.manifestBytes ? undefined : readStream(opened.fd, limits.manifestBytes, (chunk) => void chunks.push(Buffer.from(chunk)));
692	    } catch (err) {
693	      findings.add("unreadable_entry", `could not be read (${errorCode(err)}); nothing could be checked against it`, AUDIT_MANIFEST_FILE);
694	      return undefined;
695	    } finally {
696	      fs.closeSync(opened.fd);
697	    }
698	    if (size === undefined) {
699	      findings.add("limit_exceeded", `manifest.json is larger than ${limits.manifestBytes} bytes; it was not read, so nothing was checked against it`, AUDIT_MANIFEST_FILE);
700	      return undefined;
701	    }
702	    const bytes = Buffer.concat(chunks);
703	    manifestSha256 = sha256Hex(bytes);
704	    if (expected !== null && expected !== manifestSha256) {
705	      findings.add("manifest_sha256_mismatch", `the manifest's SHA-256 is ${manifestSha256}; you expected ${expected}. This is not the manifest that hash was taken from.`, AUDIT_MANIFEST_FILE);
706	    }
707	
708	    let text: string;
709	    try {
710	      text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
711	    } catch {
712	      findings.add("manifest_malformed", "manifest.json is not valid UTF-8", AUDIT_MANIFEST_FILE);
713	      return undefined;
714	    }
715	    if (nestsDeeperThan(text, limits.jsonDepth)) {
716	      findings.add("limit_exceeded", `manifest.json nests deeper than ${limits.jsonDepth} levels; it was not parsed`, AUDIT_MANIFEST_FILE);
717	      return undefined;
718	    }
719	    let parsed: unknown;
720	    try {
721	      parsed = JSON.parse(text);
722	    } catch {
723	      findings.add("manifest_malformed", "manifest.json is not valid JSON", AUDIT_MANIFEST_FILE);
724	      return undefined;
725	    }
726	    if (!isObject(parsed)) {
727	      findings.add("manifest_malformed", "manifest.json is not a JSON object", AUDIT_MANIFEST_FILE);
728	      return undefined;
729	    }
730	    if (parsed.schema_version !== AUDIT_BUNDLE_SCHEMA_VERSION) {
731	      if (Number.isSafeInteger(parsed.schema_version)) {
732	        unsupported = true;
733	        findings.add("unsupported_version", `this bundle declares schema_version ${parsed.schema_version}; this nexus reads schema_version ${AUDIT_BUNDLE_SCHEMA_VERSION}. Nothing in it was checked.`, AUDIT_MANIFEST_FILE);
734	      } else findings.add("manifest_malformed", "schema_version is missing or not an integer", AUDIT_MANIFEST_FILE);
735	      return undefined;
736	    }
737	    if (typeof parsed.bundle_id === "string" && BUNDLE_ID.test(parsed.bundle_id)) bundleId = parsed.bundle_id;
738	    if (`${canonicalJson(parsed)}\n` !== text) {
739	      findings.add("manifest_not_canonical", "manifest.json parses, but its bytes are not the canonical form (sorted keys, no whitespace, one trailing newline, no repeated key): it was changed after it was written", AUDIT_MANIFEST_FILE);
740	    }
741	    if (isHex64(parsed.root_sha256)) {
742	      const rootHash = manifestRoot(parsed);
743	      if (rootHash !== parsed.root_sha256) findings.add("manifest_root_mismatch", `the manifest's content hashes to ${rootHash}; it records root_sha256 ${parsed.root_sha256}: it was changed after it was written`, AUDIT_MANIFEST_FILE);
744	    }
745	    const problems = manifestProblems(parsed, limits);
746	    for (const problem of problems) findings.add(problem.kind, problem.message, AUDIT_MANIFEST_FILE);
747	    if (problems.length) return undefined;
748	    const valid = parsed as unknown as AuditManifest;
749	
750	    const chain = verifyChain(valid.files);
751	    const head = headOf(chain);
752	    if (valid.files.length > 0 && chain.status !== "intact") {
753	      findings.add("manifest_chain_broken", `the file entries: ${chain.status === "unchained" ? "no entry carries a chain link" : describeChain(chain)}`, AUDIT_MANIFEST_FILE);
754	    } else if ((head?.seq ?? null) !== (valid.files_head?.seq ?? null) || (head?.hash ?? null) !== (valid.files_head?.hash ?? null)) {
755	      findings.add("manifest_chain_broken", `the file entries end at ${head ? `entry ${head.seq} (${head.hash})` : "nothing"}; files_head records ${valid.files_head ? `entry ${valid.files_head.seq} (${valid.files_head.hash})` : "nothing"}`, AUDIT_MANIFEST_FILE);
756	    }
757	    return valid;
758	  }
759	
760	  /** The real tree against the manifest's path set, then every listed file's bytes, then every chained log. */
761	  function checkTree(m: AuditManifest): void {
762	    listed = m.files.length;
763	    const entries = new Map(m.files.map((entry) => [entry.path, entry]));
764	    const directories = new Set<string>();
765	    for (const p of entries.keys()) {
766	      const segments = p.split("/");
767	      for (let i = 1; i < segments.length; i++) directories.add(segments.slice(0, i).join("/"));
768	    }
769	    const chained = new Map(m.chained_logs.map((log) => [log.path, log]));
770	
771	    // 1. What is really there. Only names read from the directories are ever joined to the root.
772	    const found = new Set<string>();
773	    const accounted = new Set<string>();
774	    const maxEntries = limits.files * limits.pathDepth + 2;
775	    let seen = 0;
776	    let complete = true;
777	    const pending: string[] = [""];
778	    walk: while (pending.length) {
779	      const rel = pending.pop()!;
780	      let dir: fs.Dir;
781	      try {
782	        dir = fs.opendirSync(rel ? path.join(root, ...rel.split("/")) : root);
783	      } catch (err) {
784	        findings.add("unreadable_entry", `the directory could not be listed (${errorCode(err)}); what it holds was not checked`, rel || ".");
785	        complete = false;
786	        continue;
787	      }
788	      try {
789	        for (let item = dir.readSync(); item; item = dir.readSync()) {
790	          const name = item.name;
791	          if (rel === "" && (name === AUDIT_MANIFEST_FILE || name === AUDIT_SIGNATURE_FILE)) continue;
792	          if (++seen > maxEntries) {
793	            findings.add("limit_exceeded", `the bundle holds more than ${maxEntries} entries; the rest were not looked at`);
794	            complete = false;
795	            break walk;
796	          }
797	          const child = rel ? `${rel}/${name}` : name;
798	          // A name that is not a valid segment cannot be in the manifest; it is reported, never opened.
799	          let stat: fs.Stats;
800	          try {
801	            stat = fs.lstatSync(path.join(root, ...child.split("/")));
802	          } catch (err) {
803	            findings.add("unreadable_entry", `could not be examined (${errorCode(err)}); it was not checked`, child);
804	            accounted.add(child);
805	            continue;
806	          }
807	          if (stat.isSymbolicLink()) {
808	            findings.add("unsafe_entry", "a symbolic link; it was not followed or read", child);
809	            accounted.add(child);
810	          } else if (stat.isDirectory()) {
811	            if (directories.has(child)) pending.push(child);
812	            else findings.add("file_unexpected", "a directory the manifest does not account for; what it holds was not read", child);
813	          } else if (!stat.isFile()) {
814	            findings.add("unsafe_entry", "not a regular file; it was not read", child);
815	            accounted.add(child);
816	          } else if (entries.has(child)) found.add(child);
817	          else findings.add("file_unexpected", "a file the manifest does not list", child);
818	        }
819	      } catch (err) {
820	        findings.add("unreadable_entry", `the directory could not be listed (${errorCode(err)}); what it holds was not checked`, rel || ".");
821	        complete = false;
822	      } finally {
823	        dir.closeSync();
824	      }
825	    }
826	
827	    // 2. Every listed file, in manifest order: present, then its bytes.
828	    let total = 0;
829	    let overTotal = false;
830	    const readLogs = new Map<string, ChainedLogReader | string>();
831	    for (const entry of m.files) {
832	      if (!found.has(entry.path)) {
833	        // An entry already reported as a link, a special file or unreadable is not also "missing"; nor is one that
834	        // may sit in a part of the tree that could not be listed.
835	        if (!accounted.has(entry.path) && complete) findings.add("file_missing", "listed in the manifest, not in the bundle", entry.path);
836	        else if (!accounted.has(entry.path)) findings.add("unreadable_entry", "listed in the manifest; not found in the part of the bundle that could be listed", entry.path);
837	        continue;
838	      }
839	      if (overTotal) continue;
840	      const opened = openRegular(path.join(root, ...entry.path.split("/")));
841	      if (!("fd" in opened)) {
842	        findings.add(opened.kind, opened.message, entry.path);
843	        continue;
844	      }
845	      const hash = createHash("sha256");
846	      const log = chained.has(entry.path) ? new ChainedLogReader(limits) : undefined;
847	      let bytes: number | undefined;
848	      try {
849	        if (opened.size > limits.fileBytes) bytes = undefined;
850	        else if (total + opened.size > limits.totalBytes) {
851	          overTotal = true;
852	          findings.add("limit_exceeded", `the files hold more than ${limits.totalBytes} bytes together; this file and those after it were not read`, entry.path);
853	          continue;
854	        } else {
855	          bytes = readStream(opened.fd, limits.fileBytes, (chunk) => {
856	            hash.update(chunk);
857	            log?.push(chunk);
858	          });
859	        }
860	      } catch (err) {
861	        findings.add("unreadable_entry", `could not be read (${errorCode(err)}); it was not checked`, entry.path);
862	        continue;
863	      } finally {
864	        fs.closeSync(opened.fd);
865	      }
866	      if (bytes === undefined) {
867	        findings.add("limit_exceeded", `larger than ${limits.fileBytes} bytes; it was not read`, entry.path);
868	        if (log) readLogs.set(entry.path, `the file is larger than ${limits.fileBytes} bytes`);
869	        continue;
870	      }
871	      total += bytes;
872	      const digest = hash.digest("hex");
873	      if (bytes !== entry.bytes || digest !== entry.sha256) {
874	        findings.add("file_altered", `the file is ${plural(bytes, "byte")} with SHA-256 ${digest}; the manifest records ${plural(entry.bytes, "byte")} with SHA-256 ${entry.sha256}`, entry.path, {
875	          expected_sha256: entry.sha256,
876	          found_sha256: digest,
877	          expected_bytes: entry.bytes,
878	          found_bytes: bytes,
879	        });
880	      } else matched++;
881	      if (log) {
882	        log.end();
883	        readLogs.set(entry.path, log.limit ?? log);
884	      }
885	    }
886	
887	    // 3. Every chained log, from the bytes just hashed: its own chain, then where it ends against the manifest.
888	    for (const recorded of m.chained_logs) {
889	      const read = readLogs.get(recorded.path);
890	      if (read === undefined || typeof read === "string") {
891	        // Not read: the file is missing, unsafe or unreadable (already a finding), or a log limit stopped the reading.
892	        if (typeof read === "string") findings.add("limit_exceeded", `the chained log was not checked: ${read}`, recorded.path);
893	        logs.push({ path: recorded.path, kind: recorded.kind, status: "not_checked", records: 0, matches_manifest: false });
894	        continue;
895	      }
896	      let verdict: ChainVerdict;
897	      try {
898	        verdict = verifyChain(read.records);
899	      } catch (err) {
900	        findings.add("limit_exceeded", `the chained log could not be checked (${errorCode(err)})`, recorded.path);
901	        logs.push({ path: recorded.path, kind: recorded.kind, status: "not_checked", records: read.records.length, matches_manifest: false });
902	        continue;
903	      }
904	      const head = headOf(verdict);
905	      const ends = head ? `its records end at record ${head.seq} (${head.hash})` : `it reads as ${describeChain(verdict)}`;
906	      const wanted = `the manifest recorded ${plural(recorded.records, "record")}${recorded.head ? ` ending at ${recorded.head.hash}` : ""}`;
907	      let matches = false;
908	      if (recorded.status === "intact" && verdict.status !== "intact") {
909	        findings.add("log_chain_broken", `${verdict.status === "unchained" ? "no record carries a chain link" : describeChain(verdict)}; the manifest recorded an intact chain`, recorded.path);
910	      } else if (verdict.status !== recorded.status || verdict.records !== recorded.records || (head?.seq ?? null) !== (recorded.head?.seq ?? null) || (head?.hash ?? null) !== (recorded.head?.hash ?? null)) {
911	        findings.add(
912	          "log_head_mismatch",
913	          recorded.status === "intact"
914	            ? `${ends}; ${wanted}. Records are missing from the end, or the log was replaced.`
915	            : `it reads as ${describeChain(verdict)}; the manifest recorded a log that was ${recorded.status} with ${plural(recorded.records, "record")}. The log was replaced.`,
916	          recorded.path,
917	        );
918	      } else matches = true;
919	      logs.push({ path: recorded.path, kind: recorded.kind, status: verdict.status, records: verdict.records, matches_manifest: matches });
920	
921	      // What the manifest says about the log that is not a failure. It is the manifest's statement, as old as the export.
922	      if (recorded.status !== "intact") notes.push(`${recorded.path} was already ${recorded.status === "broken" ? "broken" : "not chained"} when it was exported; its integrity before export cannot be shown.`);
923	      if (recorded.closed === false) notes.push(`${recorded.path} was not closed when it was exported: it has no end record (still recording, stopped early, or records were already missing from the end).`);
924	      if (recorded.source && !recorded.source.complete) notes.push(`${recorded.path} is a bounded excerpt: the first ${plural(recorded.records, "record")} of a source log of ${recorded.source.records}.`);
925	    }
926	  }
927	}
928	
929	// ---- Text ----
930	
931	/** Stated on every intact result of a bundle whose signature was not checked against a key, which is every unsigned one. */
932	export const AUDIT_UNSIGNED_CAVEAT = "This bundle is NOT SIGNED: anyone able to write it could have replaced its files and the manifest together.";
933	
934	/** The result as text for a person. The classes of wording are fixed; a consumer reads the JSON document instead. */
935	export function renderAuditVerifyText(document: AuditVerifyOutput): string {
936	  if (!("result" in document)) return `ERROR, NOTHING WAS CHECKED: ${document.error}\n`;
937	  const n = document.files.listed;
938	  const match = n === 0 ? "the manifest lists no files" : n === 1 ? "the 1 file matches the manifest" : `all ${n} files match the manifest`;
939	  const lines: string[] = [];
940	  switch (document.result) {
941	    case "intact_signed":
942	      lines.push(`INTACT, SIGNED: ${match}, and the manifest is signed by the key you supplied (sha256 ${document.public_key_sha256}).`);
943	      break;
944	    case "intact_unsigned":
945	      lines.push(
946	        `INTACT BY HASH ONLY: ${match}. ${AUDIT_UNSIGNED_CAVEAT} ${
947	          document.expected_manifest_sha256 === null
948	            ? `To rule that out, compare the manifest hash ${document.manifest_sha256} with one recorded at export.`
949	            : `The manifest hash ${document.manifest_sha256} is the one you expected, which rules that out only as far as your copy of the hash was kept where the bundle's writer could not change it.`
950	        }`,
951	      );
952	      break;
953	    case "signature_unchecked":
954	      lines.push(
955	        `FILES MATCH, SIGNATURE NOT CHECKED: ${match}. The bundle carries a signature (${AUDIT_SIGNATURE_FILE}) that was NOT checked: no public key was given. Until it is checked, treat the bundle as unsigned: anyone able to write it could have replaced its files, the manifest and the signature together.`,
956	      );
957	      break;
958	    case "tampered":
959	      lines.push(`NOT INTACT: ${plural(document.findings_total, "problem")} found. This bundle is not the one its manifest describes, or it could not be fully checked; do not rely on it.`);
960	      break;
961	    case "unsupported_version":
962	      lines.push("NOT CHECKED: this bundle's schema version is not one this nexus reads. Nothing in it was verified.");
963	      break;
964	  }
965	  for (const finding of document.findings) lines.push(`  ${finding.kind}${finding.path === undefined ? "" : ` ${finding.path}`}: ${finding.message}`);
966	  if (document.findings_total > document.findings.length) lines.push(`  ... and ${document.findings_total - document.findings.length} more not listed.`);
967	  if (document.result !== "intact_unsigned" && document.manifest_sha256) lines.push(`manifest sha256: ${document.manifest_sha256}`);
968	  for (const log of document.chained_logs) {
969	    lines.push(`chained log ${log.path}: ${log.status === "not_checked" ? "NOT CHECKED" : `${log.status}, ${plural(log.records, "record")}`}${log.matches_manifest ? ", as the manifest recorded" : ", NOT as the manifest recorded"}`);
970	  }
971	  for (const note of document.notes) lines.push(`note: ${note}`);
972	  return `${lines.join("\n")}\n`;
973	}
