1	/**
2	 * What the audit-bundle tests share (GV-2): a fixture with one artefact of every kind, the schema checks every manifest
3	 * and result document goes through, a helper that re-seals a manifest the way someone rewriting a bundle would, and a
4	 * spy that records every path handed to `node:fs`.
5	 */
6	import assert from "node:assert/strict";
7	import fs from "node:fs";
8	import os from "node:os";
9	import path from "node:path";
10	import { createHash } from "node:crypto";
11	import { syncBuiltinESMExports } from "node:module";
12	import { auditBundleSchemaFile, auditVerifyResultSchemaFile } from "../../scripts/gen_audit_schema.mjs";
13	import { AUDIT_BUNDLE_SCHEMA_VERSION, AUDIT_VERIFY_RESULT_SCHEMA_VERSION, auditExitCode, type AuditExitName, type AuditManifest, type AuditVerifyOutput, type AuditVerifyResult } from "../../src/audit_contract.js";
14	import { renderAuditVerifyText, verifyAuditBundle, writeAuditBundle, type AuditBundleInput, type VerifyAuditBundleOptions, type WrittenAuditBundle } from "../../src/core/audit_bundle.js";
15	import { canonicalJson, linkRecord, type ChainLink } from "../../src/core/hash_chain.js";
16	import { validate, type Schema } from "./json_schema.js";
17	
18	export const AUDIT_BUNDLE_SCHEMA_TEXT = fs.readFileSync(auditBundleSchemaFile(AUDIT_BUNDLE_SCHEMA_VERSION), "utf8");
19	export const AUDIT_BUNDLE_SCHEMA: Schema = JSON.parse(AUDIT_BUNDLE_SCHEMA_TEXT);
20	export const AUDIT_VERIFY_SCHEMA_TEXT = fs.readFileSync(auditVerifyResultSchemaFile(AUDIT_VERIFY_RESULT_SCHEMA_VERSION), "utf8");
21	export const AUDIT_VERIFY_SCHEMA: Schema = JSON.parse(AUDIT_VERIFY_SCHEMA_TEXT);
22	
23	export const sha256 = (data: Uint8Array | string): string => createHash("sha256").update(data).digest("hex");
24	
25	const tempDirs: string[] = [];
26	/** A fresh directory; `cleanTemp` (call it from `after`) removes every one made. */
27	export function tempDir(): string {
28	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-gv2-"));
29	  tempDirs.push(dir);
30	  return dir;
31	}
32	export function cleanTemp(): void {
33	  for (const dir of tempDirs.splice(0)) fs.rmSync(dir, { recursive: true, force: true });
34	}
35	
36	/** Chained records as one JSON line each, the form of a flight log and of the config-attempt log. */
37	export function chainedLines(contents: object[]): string[] {
38	  const lines: string[] = [];
39	  let previous: ChainLink | undefined;
40	  for (const content of contents) {
41	    const record = linkRecord(content, previous);
42	    previous = record.chain;
43	    lines.push(JSON.stringify(record));
44	  }
45	  return lines;
46	}
47	
48	export const FLIGHT_PATH = "flights/flight-1.flightlog";
49	export const ATTEMPTS_PATH = "verification/config-attempts.jsonl";
50	export const FLIGHT_EVENTS = [
51	  { type: "session_start", timestamp: 0, payload: { flightId: "flight-1", model: "m", taskPrompt: "do the thing" } },
52	  { type: "turn_start", step: 1, timestamp: 1, payload: { prompt: "do the thing" } },
53	  { type: "tool_call", step: 1, timestamp: 2, payload: { name: "read_file", args: { path: "a.ts" } } },
54	  { type: "tool_result", step: 1, timestamp: 3, payload: { ok: true, output: "contents héllo ✓" } },
55	  { type: "session_end", timestamp: 4, payload: { summary: "done", success: true } },
56	];
57	const text = (value: string): Uint8Array => Buffer.from(value, "utf8");
58	const json = (value: unknown): Uint8Array => text(`${JSON.stringify(value, null, 2)}\n`);
59	
60	/** One artefact of every role the first slices write, two of them chained logs. The same bytes on every call. */
61	export function fixtureInput(): AuditBundleInput {
62	  return {
63	    subject: { kind: "task", task_id: "task-1", session_id: null, store: "tasks", workspace_path: "/work/repo", workspace_sha256: sha256("/work/repo"), status: "completed", updated_at: "2026-11-22T09:00:00.000Z", at_rest: true },
64	    nexus: { version: "1.3.0", commit: "0123abc", dirty: false },
65	    redaction: "standard",
66	    artefacts: [
67	      { path: "session/export.json", role: "session_export", bytes: json({ format: "nexus-session-export/2", messages: [{ role: "user", content: "do the thing" }] }) },
68	      { path: "session/export.md", role: "session_export_markdown", bytes: text("# Session\n\ndo the thing\n") },
69	      { path: "receipts/validation-receipts.json", role: "validation_receipts", bytes: json([{ id: "r1", command: "npm test", passed: true }]) },
70	      { path: "receipts/last-turn.json", role: "last_turn", bytes: json({ execution: "COMPLETED", outcome: "VERIFIED" }) },
71	      { path: "verification/attempts.json", role: "verification_attempts", bytes: json([{ attempt: 1, verdict: "pass" }]) },
72	      { path: ATTEMPTS_PATH, role: "verification_config_attempts", bytes: text(`${chainedLines([{ path: "package.json", decision: "blocked" }, { path: "vitest.config.ts", decision: "approved" }]).join("\n")}\n`) },
73	      { path: "evidence/provenance.json", role: "evidence_provenance", bytes: json({ "REQ-1": ["test:a"] }) },
74	      { path: "evidence/findings.json", role: "evidence_findings", bytes: json([]) },
75	      { path: "evidence/diffs/op-1.diff", role: "diff", bytes: text("@@ -1 +1 @@\n-a\n+b\n") },
76	      { path: FLIGHT_PATH, role: "flight_log", bytes: text(`${chainedLines(FLIGHT_EVENTS).join("\n")}\n`) },
77	    ],
78	    chainedLogs: [
79	      { path: FLIGHT_PATH, kind: "flight", closed: true, selection: "explicit" },
80	      { path: ATTEMPTS_PATH, kind: "verification_config_attempts" },
81	    ],
82	    omitted: [{ artefact: "traces", reason: "not requested" }],
83	  };
84	}
85	
86	export const FIXED_NOW = (): Date => new Date("2026-11-22T10:00:00.000Z");
87	export const FIXED_ID = "ab".repeat(16);
88	
89	export function assertManifestValid(manifest: unknown): void {
90	  assert.deepEqual(validate(manifest, AUDIT_BUNDLE_SCHEMA, AUDIT_BUNDLE_SCHEMA), [], "the manifest does not validate against docs/protocol/audit-bundle schema");
91	}
92	
93	/** Writes `input` as a bundle named `bundle` in a fresh directory, and checks the manifest written against the schema. */
94	export function writeFixture(input: AuditBundleInput = fixtureInput()): WrittenAuditBundle & { parent: string } {
95	  const parent = tempDir();
96	  const written = writeAuditBundle(input, { out: path.join(parent, "bundle"), now: FIXED_NOW, bundleId: FIXED_ID, durable: false });
97	  assertManifestValid(written.manifest);
98	  assertManifestValid(JSON.parse(fs.readFileSync(path.join(written.dir, "manifest.json"), "utf8")));
99	  return { ...written, parent };
100	}
101	
102	export interface Checked {
103	  document: AuditVerifyOutput;
104	  /** The document as a result; an assertion fails when it is an error document. */
105	  result: AuditVerifyResult;
106	  exit: AuditExitName;
107	  code: number;
108	  text: string;
109	  kinds: string[];
110	}
111	
112	/** Verifies a bundle; every document produced goes through the published schema and agrees with its exit-code row. */
113	export function check(dir: string, options?: VerifyAuditBundleOptions): Checked {
114	  const { document, exit } = verifyAuditBundle(dir, options);
115	  assert.deepEqual(validate(document, AUDIT_VERIFY_SCHEMA, AUDIT_VERIFY_SCHEMA), [], "the result does not validate against docs/protocol/audit-verify-result schema");
116	  assert.equal(document.exitCode, auditExitCode(exit));
117	  assert.equal(Object.keys(document)[0], "schema_version");
118	  if ("result" in document) assert.equal(document.result, exit);
119	  return {
120	    document,
121	    get result(): AuditVerifyResult {
122	      assert.ok("result" in document, `expected a result, got the error document: ${JSON.stringify(document)}`);
123	      return document;
124	    },
125	    exit,
126	    code: document.exitCode,
127	    text: renderAuditVerifyText(document),
128	    kinds: "result" in document ? document.findings.map((finding) => finding.kind) : [],
129	  };
130	}
131	
132	export const manifestFile = (dir: string): string => path.join(dir, "manifest.json");
133	export const readManifestText = (dir: string): string => fs.readFileSync(manifestFile(dir), "utf8");
134	export const readManifest = (dir: string): AuditManifest => JSON.parse(readManifestText(dir));
135	
136	/**
137	 * What someone rewriting a bundle does: recompute every file-entry link, the head and the root for the manifest as it
138	 * now is, and write it in canonical form. Written apart from the library's own writer on purpose.
139	 */
140	export function reseal(dir: string, manifest: Record<string, any>): string {
141	  let previous: ChainLink | undefined;
142	  manifest.files = manifest.files.map((entry: Record<string, unknown>) => {
143	    const { chain: _chain, ...content } = entry;
144	    const linked = linkRecord(content, previous);
145	    previous = linked.chain;
146	    return linked;
147	  });
148	  manifest.files_head = previous ? { seq: previous.seq, hash: previous.hash } : null;
149	  delete manifest.root_sha256;
150	  manifest.root_sha256 = sha256(canonicalJson(manifest));
151	  const bytes = `${canonicalJson(manifest)}\n`;
152	  fs.writeFileSync(manifestFile(dir), bytes);
153	  return sha256(bytes);
154	}
155	
156	/** Replaces a payload file and re-seals the manifest to match: the rewrite an unsigned bundle cannot reveal. */
157	export function rewritePayload(dir: string, file: string, bytes: Uint8Array | string): string {
158	  const data = typeof bytes === "string" ? Buffer.from(bytes) : bytes;
159	  fs.writeFileSync(path.join(dir, file), data);
160	  const manifest = readManifest(dir) as Record<string, any>;
161	  const entry = manifest.files.find((candidate: { path: string }) => candidate.path === file);
162	  entry.bytes = data.length;
163	  entry.sha256 = sha256(data);
164	  return reseal(dir, manifest);
165	}
166	
167	/** Flips one bit of the byte in the middle of a file. */
168	export function flipByte(file: string): void {
169	  const bytes = fs.readFileSync(file);
170	  bytes[Math.floor(bytes.length / 2)] ^= 0x01;
171	  fs.writeFileSync(file, bytes);
172	}
173	
174	/**
175	 * Runs `run` with every function of `node:fs` (and `fs.promises`) wrapped, and returns each path one was called with:
176	 * every path the library opened, listed or examined (the named exports of `node:fs` are re-synced, so a module that
177	 * imports the namespace is seen too). `events` is the same in order with the function's name, plus each `fsyncSync`
178	 * under the path its descriptor was opened with.
179	 */
180	export function spyFs<T>(run: () => T): { value: T; paths: string[]; events: Array<{ fn: string; path: string }> } {
181	  const paths: string[] = [];
182	  const events: Array<{ fn: string; path: string }> = [];
183	  const open = new Map<number, string>();
184	  const restore: Array<() => void> = [];
185	  for (const holder of [fs, fs.promises] as any[]) {
186	    for (const key of Object.keys(holder)) {
187	      const original = holder[key];
188	      if (typeof original !== "function" || /^[A-Z]/.test(key)) continue;
189	      holder[key] = function (this: unknown, ...args: unknown[]) {
190	        const first = args[0];
191	        if (typeof first === "string" || Buffer.isBuffer(first) || first instanceof URL) {
192	          paths.push(String(first));
193	          events.push({ fn: key, path: String(first) });
194	        }
195	        if (key === "fsyncSync") events.push({ fn: key, path: open.get(first as number) ?? "(unknown descriptor)" });
196	        if (key === "closeSync") open.delete(first as number);
197	        const value = original.apply(this, args);
198	        if (key === "openSync") open.set(value, String(first));
199	        return value;
200	      };
201	      restore.push(() => {
202	        holder[key] = original;
203	      });
204	    }
205	  }
206	  syncBuiltinESMExports();
207	  try {
208	    return { value: run(), paths, events };
209	  } finally {
210	    for (const undo of restore) undo();
211	    syncBuiltinESMExports();
212	  }
213	}
214	
215	/** Every file under `dir` as `relative path -> hex of bytes`, and every entry's mode. */
216	export function snapshot(dir: string): { files: Record<string, string>; modes: Record<string, number> } {
217	  const files: Record<string, string> = {};
218	  const modes: Record<string, number> = { ".": fs.lstatSync(dir).mode & 0o777 };
219	  const walk = (rel: string): void => {
220	    for (const name of fs.readdirSync(path.join(dir, rel)).sort()) {
221	      const child = rel ? `${rel}/${name}` : name;
222	      const stat = fs.lstatSync(path.join(dir, child));
223	      modes[child] = stat.mode & 0o777;
224	      if (stat.isDirectory()) walk(child);
225	      else files[child] = fs.readFileSync(path.join(dir, child)).toString("hex");
226	    }
227	  };
228	  walk("");
229	  return { files, modes };
230	}
