77	/** Text from a bundle made safe to print: anything outside printable ASCII is escaped, and it is cut at 200 characters. */
78	function shown(text: string): string {
79	  const escaped = text.replace(/[^\x20-\x7e]/g, (c) => `\\u{${c.charCodeAt(0).toString(16)}}`);
