85	/** Why `value` is not a valid payload path; undefined when it is one. */
86	export function auditPathProblem(value: unknown, limits: AuditLimits = AUDIT_LIMITS): string | undefined {
87	  if (typeof value !== "string" || value.length === 0) return "is not a non-empty string";
88	  if (value.startsWith("/")) return "is absolute";
89	  const segments = value.split("/");
90	  if (segments.length > limits.pathDepth) return `has more than ${limits.pathDepth} segments`;
91	  for (const segment of segments) {
92	    if (segment.length === 0) return "has an empty segment";
93	    if (segment === "." || segment === "..") return `has a ${JSON.stringify(segment)} segment`;
94	    if (segment.length > limits.pathSegmentChars) return `has a segment longer than ${limits.pathSegmentChars} characters`;
95	    if (!SEGMENT.test(segment)) return "has a character outside A-Z a-z 0-9 . _ -";
96	  }
97	  const lower = value.toLowerCase();
98	  if (lower === AUDIT_MANIFEST_FILE || lower === AUDIT_SIGNATURE_FILE) return "is a name reserved for the bundle itself";
99	  return undefined;
100	}
