102	/**
103	 * What is wrong with a set of valid payload paths taken together: two that differ only by case, a path that is both a
104	 * file and a directory, or a directory spelled two ways. Such a set cannot be laid out the same on every file system.
105	 */
106	function pathSetProblems(paths: readonly string[]): string[] {
107	  const problems: string[] = [];
108	  const files = new Map<string, string>();
109	  for (const p of paths) {
110	    const lower = p.toLowerCase();
111	    const other = files.get(lower);
112	    if (other !== undefined) problems.push(other === p ? `${p} is listed twice` : `${other} and ${p} differ only by case`);
113	    else files.set(lower, p);
114	  }
115	  const directories = new Map<string, string>();
116	  for (const p of paths) {
117	    const segments = p.split("/");
118	    for (let i = 1; i < segments.length; i++) {
119	      const prefix = segments.slice(0, i).join("/");
120	      const lower = prefix.toLowerCase();
121	      if (files.has(lower)) problems.push(`${files.get(lower)} is a file, and ${p} needs it to be a directory`);
122	      const spelled = directories.get(lower);
123	      if (spelled === undefined) directories.set(lower, prefix);
124	      else if (spelled !== prefix) problems.push(`the directories ${spelled} and ${prefix} differ only by case`);
125	    }
126	  }
127	  return [...new Set(problems)];
128	}
