130	/** True when arrays and objects nest deeper than `max`. Counted on the text, so it runs before anything recursive sees the value. */
131	function nestsDeeperThan(text: string, max: number): boolean {
132	  let depth = 0;
133	  let inString = false;
134	  for (let i = 0; i < text.length; i++) {
135	    const c = text.charCodeAt(i);
136	    if (inString) {
137	      if (c === 92) i++;
138	      else if (c === 34) inString = false;
139	    } else if (c === 34) inString = true;
140	    else if (c === 91 || c === 123) {
141	      if (++depth > max) return true;
142	    } else if (c === 93 || c === 125) depth--;
143	  }
144	  return false;
145	}
