147	/**
148	 * Reads a chained log from its bytes, fed in pieces: one JSON record per line, blank lines skipped, a line that is not
149	 * a JSON object kept as `null` so `verifyChain` reports it at its position. Stops at the first limit it meets.
150	 */
151	class ChainedLogReader {
152	  readonly records: unknown[] = [];
153	  /** The limit that stopped the reading; the records are then incomplete and must not be judged. */
154	  limit: string | undefined;
155	  private pending: Buffer[] = [];
156	  private pendingBytes = 0;
157	
158	  constructor(private readonly limits: AuditLimits) {}
159	
160	  push(chunk: Uint8Array): void {
161	    let start = 0;
162	    while (this.limit === undefined && start < chunk.length) {
163	      const newline = chunk.indexOf(10, start);
164	      const end = newline === -1 ? chunk.length : newline;
165	      this.pendingBytes += end - start;
166	      if (this.pendingBytes > this.limits.logLineBytes) {
167	        this.limit = `a line is longer than ${this.limits.logLineBytes} bytes`;
168	        return;
169	      }
170	      this.pending.push(Buffer.from(chunk.subarray(start, end)));
171	      if (newline === -1) return;
172	      this.line();
173	      start = newline + 1;
174	    }
175	  }
176	
177	  end(): void {
178	    if (this.limit === undefined && this.pendingBytes > 0) this.line();
179	  }
180	
181	  private line(): void {
182	    const bytes = Buffer.concat(this.pending);
183	    this.pending = [];
184	    this.pendingBytes = 0;
185	    let text: string;
186	    try {
187	      text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
188	    } catch {
189	      this.add(null);
190	      return;
191	    }
192	    if (text.trim().length === 0) return;
193	    if (nestsDeeperThan(text, this.limits.jsonDepth)) {
194	      this.limit = `record ${this.records.length} nests deeper than ${this.limits.jsonDepth} levels`;
195	      return;
196	    }
197	    try {
198	      const parsed: unknown = JSON.parse(text);
199	      this.add(parsed !== null && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null);
200	    } catch {
201	      this.add(null);
202	    }
203	  }
204	
205	  private add(record: unknown): void {
206	    if (this.records.length >= this.limits.logRecords) this.limit = `it holds more than ${this.limits.logRecords} records`;
207	    else this.records.push(record);
208	  }
209	}
