214	// ---- The manifest's shape ----
215	
216	type Problem = { kind: AuditFindingKind; message: string };
217	const isObject = (value: unknown): value is Record<string, unknown> => value !== null && typeof value === "object" && !Array.isArray(value);
218	const isCount = (value: unknown): value is number => Number.isSafeInteger(value) && (value as number) >= 0;
219	const isHex64 = (value: unknown): value is string => typeof value === "string" && HEX64.test(value);
220	const isStringOrNull = (value: unknown): boolean => value === null || typeof value === "string";
221	const isHead = (value: unknown): boolean => isObject(value) && isCount(value.seq) && isHex64(value.hash);
222	
223	/**
224	 * Everything about a parsed manifest that is not a manifest of this version: members missing or of the wrong type, and
225	 * the path rules. It does not check hashes or the chain. The writer runs it on what it is about to write, so a bundle
226	 * the writer produces is one the verifier accepts.
227	 */
228	function manifestProblems(m: Record<string, unknown>, limits: AuditLimits): Problem[] {
229	  const problems: Problem[] = [];
230	  const bad = (message: string): void => void problems.push({ kind: "manifest_malformed", message });
231	  const over = (message: string): void => void problems.push({ kind: "limit_exceeded", message });
232	
233	  if (m.format !== AUDIT_BUNDLE_FORMAT) bad(`format is not ${JSON.stringify(AUDIT_BUNDLE_FORMAT)}`);
234	  if (typeof m.bundle_id !== "string" || !BUNDLE_ID.test(m.bundle_id)) bad("bundle_id is not 32 lowercase hex characters");
235	  if (typeof m.created_at !== "string" || m.created_at.length > 64 || Number.isNaN(Date.parse(m.created_at))) bad("created_at is not a timestamp");
236	  if (!isObject(m.nexus) || typeof m.nexus.version !== "string" || typeof m.nexus.commit !== "string" || typeof m.nexus.dirty !== "boolean") bad("nexus is not { version, commit, dirty }");
237	  const s = m.subject;
238	  if (
239	    !isObject(s) ||
240	    (s.kind !== "task" && s.kind !== "session") ||
241	    (s.store !== "tasks" && s.store !== "sessions") ||
242	    ![s.task_id, s.session_id, s.workspace_path, s.status, s.updated_at].every(isStringOrNull) ||
243	    !(s.workspace_sha256 === null || isHex64(s.workspace_sha256)) ||
244	    typeof s.at_rest !== "boolean"
245	  ) bad("subject is missing a member or has one of the wrong type");
246	  if (m.redaction !== "standard" && m.redaction !== "strict") bad('redaction is not "standard" or "strict"');
247	  if (!isHex64(m.root_sha256)) bad("root_sha256 is not a SHA-256 in lowercase hex");
248	  if (!(m.files_head === null || isHead(m.files_head))) bad("files_head is not null or { seq, hash }");
249	  if (!Array.isArray(m.omitted) || !m.omitted.every((o) => isObject(o) && typeof o.artefact === "string" && typeof o.reason === "string")) bad("omitted is not a list of { artefact, reason }");
250	
251	  const paths: string[] = [];
252	  if (!Array.isArray(m.files)) bad("files is not a list");
253	  else if (m.files.length > limits.files) over(`the manifest lists ${m.files.length} files; a bundle holds at most ${limits.files}`);
254	  else {
255	    let total = 0;
256	    let previous: string | undefined;
257	    for (const [i, entry] of m.files.entries()) {
258	      if (!isObject(entry)) {
259	        bad(`files[${i}] is not an object`);
260	        continue;
261	      }
262	      const pathProblem = auditPathProblem(entry.path, limits);
263	      if (pathProblem) {
264	        bad(`files[${i}].path ${typeof entry.path === "string" ? `${JSON.stringify(shown(entry.path))} ` : ""}${pathProblem}`);
265	        continue;
266	      }
267	      const p = entry.path as string;
268	      paths.push(p);
269	      if (previous !== undefined && !(previous < p) && previous !== p) bad(`files is not sorted by path at files[${i}] (${p})`);
270	      previous = p;
271	      if (!isCount(entry.bytes)) bad(`files[${i}].bytes is not a size`);
272	      else {
273	        if (entry.bytes > limits.fileBytes) over(`${p} is recorded as ${entry.bytes} bytes; a file holds at most ${limits.fileBytes}`);
274	        total += entry.bytes;
275	      }
276	      if (!isHex64(entry.sha256)) bad(`files[${i}].sha256 is not a SHA-256 in lowercase hex`);
277	      if (!(AUDIT_FILE_ROLES as readonly unknown[]).includes(entry.role)) bad(`files[${i}].role is not a known role`);
278	    }
279	    for (const problem of pathSetProblems(paths)) bad(problem);
280	    if (total > limits.totalBytes) over(`the files are recorded as ${total} bytes together; a bundle holds at most ${limits.totalBytes}`);
281	  }
282	
283	  if (!Array.isArray(m.chained_logs)) bad("chained_logs is not a list");
284	  else {
285	    const seen = new Set<string>();
286	    for (const [i, log] of m.chained_logs.entries()) {
287	      const at = `chained_logs[${i}]`;
288	      if (!isObject(log)) {
289	        bad(`${at} is not an object`);
290	        continue;
291	      }
292	      if (typeof log.path !== "string" || !paths.includes(log.path)) bad(`${at}.path is not one of the listed files`);
293	      else if (seen.has(log.path)) bad(`${at}.path ${log.path} is listed twice`);
294	      else seen.add(log.path);
295	      if (!(AUDIT_CHAINED_LOG_KINDS as readonly unknown[]).includes(log.kind)) bad(`${at}.kind is not a known kind`);
296	      if (!isCount(log.records)) bad(`${at}.records is not a count`);
297	      if (log.status !== "intact" && log.status !== "unchained" && log.status !== "broken") bad(`${at}.status is not a chain status`);
298	      if (log.head !== undefined && !isHead(log.head)) bad(`${at}.head is not { seq, hash }`);
299	      if (log.status === "intact" && isCount(log.records) && (log.records > 0) !== (log.head !== undefined)) bad(`${at}: an intact log has a head exactly when it has records`);
300	      if (log.closed !== undefined && typeof log.closed !== "boolean") bad(`${at}.closed is not a boolean`);
301	      if (log.selection !== undefined && log.selection !== "explicit" && log.selection !== "time_window") bad(`${at}.selection is not a known selection`);
302	      const source = log.source;
303	      if (
304	        source !== undefined &&
305	        !(isObject(source) && isCount(source.records) && (source.head === undefined || isHead(source.head)) && typeof source.closed === "boolean" && isCount(source.bytes) && isHex64(source.sha256) && typeof source.complete === "boolean")
306	      ) bad(`${at}.source is missing a member or has one of the wrong type`);
307	    }
308	  }
309	  return problems;
310	}
