373	/** The manifest for `input`. Throws AuditBundleError for anything the verifier would refuse. Nothing is read or written. */
374	export function buildAuditManifest(input: AuditBundleInput, options: AuditManifestOptions = {}): AuditManifest {
375	  const limits: AuditLimits = AUDIT_LIMITS;
376	  if (input.artefacts.length > limits.files) throw new AuditBundleError(`${input.artefacts.length} files; a bundle holds at most ${limits.files}`);
377	  for (const artefact of input.artefacts) {
378	    const problem = auditPathProblem(artefact.path);
379	    if (problem) throw new AuditBundleError(`artefact path ${JSON.stringify(shown(String(artefact.path)))} ${problem}`);
380	    if (!(artefact.bytes instanceof Uint8Array)) throw new AuditBundleError(`${artefact.path}: bytes is not a Uint8Array`);
381	  }
382	  const artefacts = [...input.artefacts].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
383	
384	  const files: AuditFileEntry[] = [];
385	  let previous: ChainLink | undefined;
386	  for (const artefact of artefacts) {
387	    const entry = linkRecord({ path: artefact.path, bytes: artefact.bytes.length, sha256: sha256Hex(artefact.bytes), role: artefact.role }, previous);
388	    previous = entry.chain;
389	    files.push(entry);
390	  }
391	
392	  const chained_logs: AuditChainedLog[] = [];
393	  for (const log of [...(input.chainedLogs ?? [])].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))) {
394	    const artefact = artefacts.find((candidate) => candidate.path === log.path);
395	    if (!artefact) throw new AuditBundleError(`chained log ${JSON.stringify(shown(String(log.path)))} is not one of the artefacts`);
396	    const reader = new ChainedLogReader(limits);
397	    reader.push(artefact.bytes);
398	    reader.end();
399	    if (reader.limit) throw new AuditBundleError(`chained log ${log.path}: ${reader.limit}`);
400	    const verdict = verifyChain(reader.records);
401	    chained_logs.push({ path: log.path, kind: log.kind, records: verdict.records, status: verdict.status, head: headOf(verdict), closed: log.closed, source: log.source, selection: log.selection });
402	  }
403	
404	  const body = {
405	    schema_version: AUDIT_BUNDLE_SCHEMA_VERSION,
406	    format: AUDIT_BUNDLE_FORMAT,
407	    bundle_id: options.bundleId ?? randomBytes(16).toString("hex"),
408	    created_at: (options.now ?? (() => new Date()))().toISOString(),
409	    nexus: { version: input.nexus.version, commit: input.nexus.commit, dirty: input.nexus.dirty },
410	    subject: input.subject,
411	    redaction: input.redaction,
412	    files,
413	    files_head: previous ? { seq: previous.seq, hash: previous.hash } : null,
414	    chained_logs,
415	    omitted: [...(input.omitted ?? [])],
416	  } satisfies Omit<AuditManifest, "root_sha256">;
417	  // Through its canonical text and back, so the manifest returned is exactly what a reader of manifest.json gets
418	  // (absent members absent, key order irrelevant) and the root is computed over that.
419	  const plain = JSON.parse(canonicalJson(body)) as Record<string, unknown>;
420	  const manifest = { ...plain, root_sha256: manifestRoot(plain) };
421	  const problems = manifestProblems(manifest, limits);
422	  if (problems.length) throw new AuditBundleError(`the bundle would not verify: ${problems.map((problem) => problem.message).join("; ")}`);
423	  if (nestsDeeperThan(canonicalJson(manifest), limits.jsonDepth)) throw new AuditBundleError(`the manifest nests deeper than ${limits.jsonDepth} levels`);
424	  const result = manifest as unknown as AuditManifest;
425	  if (auditManifestBytes(result).length > limits.manifestBytes) throw new AuditBundleError(`the manifest is larger than ${limits.manifestBytes} bytes`);
426	  return result;
427	}
