570	  private saveTaskStateLocked(state: DurableTaskState, workspacePaths: WorkspacePath[], options: { historical?: boolean } = {}): DurableTaskState {
571	    if (!state.taskId) {
572	      throw new TaskStateWriteError("unknown", "Missing required taskId");
573	    }
574	    if (state.schemaVersion !== undefined && (!Number.isSafeInteger(state.schemaVersion) || state.schemaVersion < 0)) {
575	      throw new TaskStateWriteError("unknown", "Invalid state schema version");
576	    }
577	
578	    if (state.worktreeBinding) {
579	      // The same rules as loadTaskState applies (state_schema.ts), so a record this build writes is one it can read.
580	      const problem = normalizeWorktreeBinding(state.worktreeBinding);
581	      if (problem?.problem === "unsupported") throw new UnsupportedSchemaVersionError(problem.version, WORKTREE_BINDING_VERSION, "binding");
582	      if (problem) throw new TaskStateWriteError(state.taskId, problem.reason);
583	    }
584	    state.updatedAt = new Date().toISOString();
585	    if (state.schemaVersion > CURRENT_STATE_SCHEMA_VERSION) throw new UnsupportedSchemaVersionError(state.schemaVersion);
586	    const lifecycleProblem = taskLifecycleProblem(state);
587	    if (lifecycleProblem) throw new TaskStateWriteError(state.taskId, lifecycleProblem);
588	    state.schemaVersion = CURRENT_STATE_SCHEMA_VERSION;
589	    // Maintain compatibility aliases
590	    state.id = state.sessionId || state.taskId;
591	    state.workspace = state.workspacePath;
592	
593	    let protectedState: DurableTaskState;
594	    let safeTaskId: string;
595	    let protectionPhase = "classification";
596	    let changedIdentityFields: string[] = [];
597	    try {
598	      const authorizedPaths = this.authorizeWorkspacePaths(workspacePaths);
599	      protectedState = redactTaskStateForPersistence(state, authorizedPaths, options);
600	      protectionPhase = "identity validation";
601	      changedIdentityFields = (["taskId", "sessionId", "id", "workspacePath"] as const).filter(
602	        (field) => protectedState[field] !== state[field]
603	      );
604	      if (protectedState.worktreeBinding?.worktreePath !== state.worktreeBinding?.worktreePath) {
605	        changedIdentityFields.push("worktreeBinding.worktreePath");
606	      }
607	      if (changedIdentityFields.length > 0) {
608	        throw new Error("Sensitive data intersects a durable state identity field");
609	      }
610	      if (!/^[A-Za-z0-9._-]{1,160}$/.test(state.taskId) || state.taskId === "." || state.taskId === "..") {
611	        throw new Error("Task identity is not a safe persistence name");
612	      }
613	      safeTaskId = state.taskId;
614	      protectionPhase = "serialization";
615	      if (!Array.isArray(protectedState.messages)) throw new Error("Task messages must be an array");
616	      if (JSON.stringify(protectedState) === undefined) throw new Error("Task state is not JSON serializable");
617	    } catch {
618	      const conflict = changedIdentityFields.length > 0 ? ` (${changedIdentityFields.join(", ")})` : "";
619	      throw new TaskStateWriteError("unknown", `Sensitive-data protection or ${protectionPhase} failed${conflict}`);
620	    }
621	
622	    const targetPath = this.getStateFilePath(safeTaskId);
623	
624	    try {
625	      const previous = this.readStoredRecord(safeTaskId, true);
626	      if (previous?.parsed.taskId && previous.parsed.taskId !== safeTaskId) {
627	        throw new TaskIdentityMismatchError(safeTaskId, previous.parsed.taskId);
628	      }
629	      if (previous) {
630	        const previousState = this.migrateIfLegacy(previous.parsed, safeTaskId);
631	        const previousProblem = taskLifecycleProblem(previousState);
632	        if (previousProblem) throw new CorruptStateError(safeTaskId, previousProblem, this.quarantineFile(previous.filePath));
633	      }
634	      if (previous) this.backupBeforeMigration(previous);
635	      const parent: TaskMessageCursor | null = previous?.version === 2 ? previous.parsed.messageLog : null;
636	      let messageLog: TaskMessageCursor | null;
637	      try {
638	        if (previous?.version === 2 && (!Object.hasOwn(previous.parsed, "messageLog") || Object.hasOwn(previous.parsed, "messages"))) {
