660	   * Loads task state from disk with strict integrity, versioning, and identity verification.
661	   * Fails closed on missing file, malformed JSON, unsupported schema, or identity mismatch.
662	   */
663	  public loadTaskState(
664	    taskId: string,
665	    expectedWorkspace?: string,
