671	  private loadTaskStateLocked(taskId: string, expectedWorkspace: string | undefined, workspacePaths: WorkspacePath[], protectOnLoad = true): DurableTaskState {
672	    const record = this.readStoredRecord(taskId)!;
673	    // Schema version check (fails closed on unsupported future versions) is performed before reading any messages.
674	    // Migrate legacy session file if necessary with pre-migration backup; publication below creates the backup first.
675	    const state: DurableTaskState = this.migrateIfLegacy(record.parsed, taskId);
676	    this.normalizeWorktreeBinding(state, taskId, record);
677	
678	    // Verify task identity binding
679	    if (state.taskId && taskId && state.taskId !== taskId && state.sessionId !== taskId) {
680	      throw new TaskIdentityMismatchError(taskId, state.taskId);
681	    }
682	    const lifecycleProblem = taskLifecycleProblem(state);
683	    if (lifecycleProblem) throw new CorruptStateError(taskId, lifecycleProblem, this.quarantineFile(record.filePath));
684	
685	    // Verify workspace binding if expectedWorkspace provided
686	    let selectedPaths = workspacePaths;
687	    let normalizedLegacyWorkspace = false;
688	    if (expectedWorkspace && state.workspacePath) {
689	      const expectedIdentity = WorkspacePath.fromSelectedWorkspace(path.resolve(expectedWorkspace));
690	      const normExpected = expectedIdentity.value;
691	      const normActual = path.resolve(state.workspacePath);
692	      if (normExpected !== normActual) {
693	        // Earlier builds recorded the active speculative worktree as the task's workspace identity.
694	        // Normalise such a record only when its own binding proves the expected root owns that exact
695	        // managed worktree; every other mismatch stays fail-closed. The load path persists the
696	        // normalised record below (workspacePath changes are protected identity fields).
697	        const binding = state.worktreeBinding;
698	        const bindingPath = binding?.worktreePath ? path.resolve(binding.worktreePath) : undefined;
699	        if (
700	          state.taskId !== taskId ||
701	          bindingPath !== normActual ||
702	          !binding ||
703	          !(isManagedWorktreePath(expectedIdentity, normActual, taskId, binding) || isNamedWorktreePath(expectedIdentity, normActual, binding))
704	        ) {
705	          throw new WorkspaceIdentityMismatchError(normExpected, normActual);
706	        }
707	        state.workspacePath = normExpected;
708	        state.workspace = normExpected;
709	        normalizedLegacyWorkspace = true;
710	      }
711	      selectedPaths = [...workspacePaths, expectedIdentity];
712	    }
713	
714	    state.messages = this.storedMessages(taskId, record);
715	    // Internal synchronous read-modify-save transactions classify the complete
716	    // state once, after mutation and before publication/return. Public recovery
717	    // reads always protect here, including migration of older plaintext state.
718	    if (!protectOnLoad) return state;
719	    try {
720	      selectedPaths = this.authorizeWorkspacePaths(selectedPaths);
721	      const protectedState = redactTaskStateForPersistence(state, selectedPaths, { historical: true });
722	      const changedIdentityFields: string[] = (["taskId", "sessionId", "id", "workspacePath"] as const).filter(
723	        (field) => protectedState[field] !== state[field]
724	      );
725	      if (protectedState.worktreeBinding?.worktreePath !== state.worktreeBinding?.worktreePath) {
726	        changedIdentityFields.push("worktreeBinding.worktreePath");
727	      }
728	      if (changedIdentityFields.length > 0) {
729	        throw new TaskStateReadError(taskId, "Sensitive data intersects durable state identity");
730	      }
731	      if (record.version < CURRENT_STATE_SCHEMA_VERSION || normalizedLegacyWorkspace || JSON.stringify(protectedState) !== JSON.stringify(state)) {
732	        // Migrate older plaintext state on disk before reporting a successful load.
733	        this.saveTaskState(protectedState, selectedPaths, { historical: true });
