401	  /** Read the atomic progress envelope without trusting a schema or a sidecar path from disk. */
402	  private readStoredRecord(taskId: string, missingAllowed = false): StoredTaskRecord | null {
403	    const filePath = this.getStateFilePath(taskId);
404	    let content: Buffer;
405	    try { content = fs.readFileSync(filePath); }
406	    catch (error: any) {
407	      if (error.code === "ENOENT") {
408	        if (missingAllowed) return null;
409	        throw new TaskStateNotFoundError(taskId, filePath);
410	      }
411	      throw new TaskStateReadError(taskId, error.message);
412	    }
413	    let parsed: any;
414	    try { parsed = JSON.parse(content.toString("utf8")); }
415	    catch {
416	      throw new CorruptStateError(taskId, "JSON parse error", this.quarantineFile(filePath));
417	    }
418	    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
419	      throw new CorruptStateError(taskId, "State file does not contain a JSON object", this.quarantineFile(filePath));
420	    }
421	    const version = parsed.schemaVersion ?? 0;
422	    if (!Number.isSafeInteger(version) || version < 0) {
423	      throw new CorruptStateError(taskId, "Invalid state schema version", this.quarantineFile(filePath));
424	    }
425	    if (version > CURRENT_STATE_SCHEMA_VERSION) throw new UnsupportedSchemaVersionError(version);
426	    if (version < 2 && parsed.messages !== undefined && parsed.messages !== null && !Array.isArray(parsed.messages)) {
427	      throw new CorruptStateError(taskId, "Legacy conversation is not an array", this.quarantineFile(filePath));
428	    }
429	    return { filePath, content, parsed, version };
430	  }
