432	  private storedMessages(taskId: string, record: StoredTaskRecord): ChatMessage[] {
433	    if (record.version < 2) {
434	      if (Array.isArray(record.parsed.messages)) return record.parsed.messages;
435	      // Version 1 requires an explicit conversation array. Absence is damage,
436	      // not an empty conversation that an interactive resume may start over.
437	      if (record.version === 1) throw new CorruptStateError(taskId, "Schema 1 state has no conversation array", this.quarantineFile(record.filePath));
438	      return [];
439	    }
440	    const log = this.getMessageLogFilePath(taskId);
441	    try {
442	      if (!Object.hasOwn(record.parsed, "messageLog") || Object.hasOwn(record.parsed, "messages")) {
443	        throw new TaskMessageLogError("corrupt", "Schema 2 progress must reference a separate message log");
444	      }
445	      return readTaskMessages(log, record.parsed.taskId, record.parsed.messageLog);
446	    } catch (error) {
447	      if (error instanceof TaskMessageLogError) {
448	        return this.messageRecoveryError(taskId, record, error);
449	      }
450	      throw new TaskStateReadError(taskId, `Failed to read message journal: ${(error as any)?.message ?? String(error)}`);
451	    }
452	  }
453	
454	  private messageRecoveryError(taskId: string, record: StoredTaskRecord, error: unknown): never {
455	    const log = this.getMessageLogFilePath(taskId);
456	    if (error instanceof TaskMessageLogError && error.kind === "future") {
457	      throw new UnsupportedSchemaVersionError(error.version ?? CURRENT_STATE_SCHEMA_VERSION + 1);
458	    }
459	    // Preserve both components for investigation. Never silently resume with
460	    // an empty conversation when a committed message record is unavailable.
461	    if (fs.existsSync(log)) this.quarantineFile(log);
462	    throw new CorruptStateError(taskId, "Committed message log is corrupt or unavailable", this.quarantineFile(record.filePath));
463	  }
