465	  /** A complete private backup must exist durably before a legacy envelope can be replaced. */
466	  private backupBeforeMigration(record: StoredTaskRecord): void {
467	    if (record.version >= CURRENT_STATE_SCHEMA_VERSION) return;
468	    const backup = `${record.filePath}.pre-migration-v${record.version}`;
469	    const syncDirectory = () => {
470	      const directory = fs.openSync(path.dirname(backup), "r");
471	      try { fs.fsyncSync(directory); }
472	      catch (error: any) { if (!["EINVAL", "ENOTSUP"].includes(error.code)) throw error; }
473	      finally { fs.closeSync(directory); }
474	    };
475	    const verifyExisting = () => {
476	      const stat = fs.lstatSync(backup);
477	      if (!stat.isFile()) {
478	        throw new TaskStateWriteError("unknown", "A different or redirected pre-migration backup already exists");
479	      }
480	      const fd = fs.openSync(backup, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
481	      try {
482	        const opened = fs.fstatSync(fd);
483	        if (!opened.isFile() || opened.dev !== stat.dev || opened.ino !== stat.ino || !fs.readFileSync(fd).equals(record.content)) {
484	          throw new TaskStateWriteError("unknown", "A different or redirected pre-migration backup already exists");
485	        }
486	        fs.fsyncSync(fd);
487	      } finally { fs.closeSync(fd); }
488	    };
489	    if (fs.existsSync(backup)) { verifyExisting(); syncDirectory(); return; }
490	    const temporary = `${backup}.${randomUUID()}.tmp`;
491	    try {
492	      writePrivateFile(temporary, record.content, { durable: true });
493	      try { fs.linkSync(temporary, backup); }
494	      catch (error: any) { if (error.code !== "EEXIST") throw error; verifyExisting(); }
495	      syncDirectory();
496	    } finally {
497	      try { fs.unlinkSync(temporary); } catch (error: any) { if (error.code !== "ENOENT") throw error; }
498	    }
499	  }
