526	
527	  private deleteTaskStateLocked(taskId: string): boolean {
528	    const filePath = this.getStateFilePath(taskId);
529	    const primaryName = path.basename(filePath);
530	    const identity = primaryName.replace(/\.json$/, "");
531	    const backupPrefix = `${primaryName}.pre-migration-v`;
532	    const companionNames = fs.readdirSync(this.baseDir).filter(name =>
533	      name === `${identity}.messages.jsonl` || name === `${identity}.history.jsonl` ||
534	      (name.startsWith(backupPrefix) && /^(0|[1-9]\d*)$/.test(name.slice(backupPrefix.length)))
535	    );
536	    const hasPrimary = fs.existsSync(filePath);
537	    if (!hasPrimary && companionNames.length === 0) return false;
538	
539	    // Verify directory syncing is available before changing the record. If the
540	    // primary is already absent, make that state durable before removing logs.
541	    fsyncDirectoryDurably(this.baseDir);
542	    let deleted = false;
543	    if (hasPrimary) {
544	      fs.unlinkSync(filePath);
545	      deleted = true;
546	      // A crash may leave either the primary or its companions, but never a
547	      // live primary whose message/history data was already removed.
548	      fsyncDirectoryDurably(this.baseDir);
549	    }
550	    for (const name of companionNames) {
551	      try {
552	        fs.unlinkSync(path.join(this.baseDir, name));
553	        deleted = true;
554	      } catch (error: any) {
555	        if (error.code !== "ENOENT") throw error;
556	      }
557	    }
558	    if (companionNames.length > 0 && deleted) fsyncDirectoryDurably(this.baseDir);
559	    return deleted;
560	  }
