844	  /**
845	   * Durably commits an authoritative task milestone after milestone prerequisites are met.
846	   */
847	  public recordMilestone(
848	    taskId: string,
849	    milestone: {
850	      name: string;
851	      phaseIndex?: number;
852	      evidenceSummary?: string;
853	      candidateId?: string;
854	    }
855	  ): DurableTaskState {
856	    return withStateStoreGuard(this.baseDir, () => this.recordMilestoneLocked(taskId, milestone));
857	  }
858	
859	  private recordMilestoneLocked(
860	    taskId: string,
861	    milestone: { name: string; phaseIndex?: number; evidenceSummary?: string; candidateId?: string }
862	  ): DurableTaskState {
863	    const state = this.loadTaskState(taskId);
864	    if (
865	      milestone.phaseIndex !== undefined &&
866	      state.activePlan &&
867	      state.activePlan[milestone.phaseIndex]
868	    ) {
869	      state.activePlan[milestone.phaseIndex].status = "completed";
870	      if (milestone.evidenceSummary) {
871	        state.activePlan[milestone.phaseIndex].detail = milestone.evidenceSummary;
872	      }
873	    }
874	
875	    if (!state.milestones) {
876	      state.milestones = [];
877	    }
878	
