71	/** Cryptographically unpredictable base36 suffix; the length stays inside the
72	 *  egress classifier's session-id whitelist (session_\d{8}_\d{6}_[a-z0-9]{1,8}). */
73	function randomBase36Suffix(length: number): string {
74	  const alphabet = "REDACTED";
75	  let suffix = "";
76	  while (suffix.length < length) {
77	    for (const byte of randomBytes(length)) {
78	      // Rejection sampling keeps the base-36 mapping unbiased (36 * 7 = 252).
79	      if (byte >= 252) continue;
80	      if (suffix.length < length) suffix += alphabet[byte % 36];
81	    }
82	  }
83	  return suffix;
84	}
