86	/** The longest prefix of `messages` no longer than `n` that does not end inside a tool exchange (a call without all its results). */
87	function completeExchangePrefix(messages: ChatMessage[], n: number): number {
88	  let end = n;
89	  while (end > 1) {
90	    let owner = end - 1;
91	    while (owner > 0 && messages[owner].role === "tool") owner--;
92	    const head = messages[owner];
93	    const calls = head.role === "assistant" ? head.tool_calls ?? [] : [];
94	    if (!calls.length) return end;
95	    const answered = new Set(messages.slice(owner + 1, end).filter((x) => x.role === "tool").map((x) => x.tool_call_id));
96	    if (calls.every((c) => answered.has(c.id))) return end;
97	    end = owner;
98	  }
99	  return end;
100	}
