201	  /**
202	   * Resolves a session ID by exact match or unique prefix (REQ-PER-104).
203	   * Throws AmbiguousSessionResumeError if a prefix matches multiple sessions.
204	   * Returns null if no matching session is found.
205	   */
206	  public resolveResumeId(prefix: string): string | null {
207	    return withStateStoreGuard(this.sessionsDir, () => this.resolveResumeIdLocked(prefix));
208	  }
209	
210	  private resolveResumeIdLocked(prefix: string): string | null {
211	    const cleanId = prefix.replace(/\.json$/, "");
212	    if (!cleanId) return null;
213	
214	    // 1. Exact match check against session file on disk
215	    const exactFilePath = path.join(this.sessionsDir, `${cleanId}.json`);
216	    if (fs.existsSync(exactFilePath)) {
217	      return cleanId;
218	    }
219	
220	    if (!fs.existsSync(this.sessionsDir)) return null;
221	
222	    // 2. Gather candidates for prefix matching
223	    const candidates = new Set<string>();
224	    const files = fs.readdirSync(this.sessionsDir);
225	    for (const file of files) {
226	      if (!file.endsWith(".json") || file === "index.json" || file.startsWith(".corrupt-")) continue;
227	      const id = file.replace(/\.json$/, "");
228	      if (id === cleanId) {
229	        return id;
230	      }
231	      if (id.startsWith(cleanId)) {
232	        candidates.add(id);
233	      }
234	    }
235	
236	    // Also check index entries in case IDs differ
237	    const indexPath = this.getIndexPath();
238	    if (fs.existsSync(indexPath)) {
239	      try {
240	        const raw = JSON.parse(fs.readFileSync(indexPath, "utf-8"));
241	        if (raw && typeof raw.sessions === "object") {
242	          for (const key of Object.keys(raw.sessions)) {
243	            const entry = raw.sessions[key];
244	            const sid = entry?.id || entry?.cleanId || key;
245	            if (sid === cleanId || key === cleanId) {
246	              return sid;
247	            }
248	            if (sid.startsWith(cleanId)) {
249	              candidates.add(sid);
250	            }
251	          }
252	        }
253	      } catch {}
254	    }
255	
256	    const candidateList = Array.from(candidates).sort();
257	    if (candidateList.length === 1) {
258	      return candidateList[0];
259	    }
260	    if (candidateList.length > 1) {
261	      throw new AmbiguousSessionResumeError(cleanId, candidateList);
262	    }
263	    return null;
264	  }
