338	  /**
339	   * RD-6: forks a saved session into a new id holding its conversation up to `atMessage` (default: all of it). The
340	   * source is only read. The cut backs up to the last complete tool exchange. Compactions whose summary is still in the
341	   * kept conversation keep their record and archive lines (copied verbatim, so resume's audit still verifies them);
342	   * a compaction whose summary the cut removed is left out, rather than letting resume "undo" it into history the
343	   * operator did not choose. A bound source gets a new isolated worktree at the same branch and workspace snapshot.
344	   * The objective ledger is carried only by a fork of the whole conversation: it describes the source's later state,
345	   * which a truncated fork never reached.
346	   */
347	  public forkSession(sourceId: string, options: { atMessage?: number; newId?: string } = {}): {
348	    id: string; sourceId: string; atMessage: number; compactions: number; worktreePath?: string; branch?: string;
349	  } {
350	    return withStateStoreGuard(this.sessionsDir, () => {
351	      const source = this.loadSession(sourceId);
352	      if (!source) throw new Error(`Session not found: ${sourceId}`);
353	      const total = source.messages.length;
354	      const asked = options.atMessage ?? total;
355	      if (!Number.isInteger(asked) || asked < 1 || asked > total) throw new Error(`The fork point must be a whole number between 1 and ${total}.`);
356	      const atMessage = completeExchangePrefix(source.messages, asked);
357	      const whole = atMessage === total;
358	      const messages = source.messages.slice(0, atMessage);
359	      const id = options.newId ?? this.generateSessionId();
360	      if (!/^[A-Za-z0-9._-]{1,160}$/.test(id) || id === "." || id === "..") throw new Error("The new session id is not a safe persistence name.");
361	      if (this.stateManager.hasTaskState(id) || fs.existsSync(this.archivedHistoryPath(id))) throw new Error(`Session ${id} already exists.`);
362	
363	      let forkWorktree: { manager: WorktreeManager; taskId: string; worktreePath: string; branch: string; createdAt: string } | undefined;
364	      const committed: string[] = Array.isArray((source.history as any)?.committedCompactions) ? (source.history as any).committedCompactions.filter((c: unknown): c is string => typeof c === "string") : [];
365	      const read = this.readArchivedHistory(source.id, new Set(committed));
366	      const kept = committed.filter((c) => {
367	        const record = read.byCompaction?.get(c)?.record;
368	        return !isCompactionRecord(record) || insertedBlockPresent(record, messages);
369	      });
370	      // The archive goes first: a record never names a compaction whose originals are not already on disk.
371	      const keep = new Set(kept);
372	      const lines: string[] = [];
373	      let archivedMessages = 0;
374	      let raw = "";
375	      try { raw = fs.readFileSync(this.archivedHistoryPath(source.id), "utf8"); } catch {}
376	      for (const line of raw.split("\n")) {
377	        if (!line.trim()) continue;
378	        let parsed: { compactionId?: string };
379	        try { parsed = JSON.parse(line); } catch { continue; }
380	        if (parsed.compactionId !== undefined && !keep.has(parsed.compactionId)) continue;
381	        lines.push(line);
382	        archivedMessages++;
383	      }
384	      const at = new Date().toISOString();
385	      const archivePath = this.archivedHistoryPath(id);
386	      try {
387	        if (source.worktreeBinding) {
388	          const manager = new WorktreeManager(source.worktreeBinding.worktreePath);
389	          const created = manager.createSessionForkWorktree(source.worktreeBinding, id);
390	          forkWorktree = { manager, taskId: created.taskId, worktreePath: created.worktreePath, branch: created.branch, createdAt: new Date().toISOString() };
391	        }
392	        if (lines.length) appendLinesDurably(archivePath, lines);
393	        this.saveSessionLocked({
394	          id,
395	          title: `Fork of ${source.title || "session"}`.slice(0, 120),
396	          workspace: source.workspace,
397	          model: source.model,
398	          ...(source.endpoint ? { endpoint: source.endpoint } : {}),
399	          messages,
400	          ...(forkWorktree ? { worktreeBinding: {
401	            taskId: forkWorktree.taskId,
402	            worktreePath: forkWorktree.worktreePath,
403	            branch: forkWorktree.branch,
404	            createdAt: forkWorktree.createdAt,
405	            kind: "task" as const,
406	            bindingVersion: WORKTREE_BINDING_VERSION,
407	          } } : {}),
408	          history: { complete: kept.length === 0, compactions: kept.length, archivedMessages, committedCompactions: kept } as any,
409	          ...(source.findings !== undefined ? { findings: source.findings } : {}),
410	          ...(source.durableNotes !== undefined ? { durableNotes: source.durableNotes } : {}),
411	          ...(source.activePlan ? { activePlan: source.activePlan } : {}),
412	          ...(whole && source.objective !== undefined ? { objective: source.objective } : {}),
413	          forkedFrom: { sessionId: source.id, atMessage, at },
414	        }, undefined, forkWorktree ? WorkspacePath.fromSelectedWorkspace(forkWorktree.manager.getGitRoot()) : undefined);
415	      } catch (err) {
416	        if (this.stateManager.hasTaskState(id)) {
417	          throw new Error(`Fork ${id} was durably saved but could not be fully indexed; its workspace is preserved. ${err instanceof Error ? err.message : String(err)}`);
418	        }
419	        try { fs.rmSync(archivePath, { force: true }); } catch {}
420	        if (forkWorktree) {
421	          const removed = forkWorktree.manager.discardWorktree(forkWorktree.taskId);
422	          if (!removed.success) throw new Error(`Fork could not be saved and its worktree cleanup failed: ${removed.error || "unknown error"}`);
423	        }
424	        throw err;
425	      }
426	      return {
427	        id, sourceId: source.id, atMessage, compactions: kept.length,
428	        ...(forkWorktree ? { worktreePath: forkWorktree.worktreePath, branch: forkWorktree.branch } : {}),
429	      };
430	    });
431	  }
