571	  private listSessionsLocked(): Array<{
572	    id: string;
573	    title: string;
574	    updatedAt: string;
575	    workspace: string;
576	    messageCount: number;
577	    pinned?: boolean;
578	  }> {
579	    if (!fs.existsSync(this.sessionsDir)) return [];
580	
581	    const indexPath = this.getIndexPath();
582	    let index: SessionIndexData | null = null;
