266	      isNamedWorktreePath(selectedWorkspace, worktreePath, value.worktreeBinding ?? {}));
267	    return validatedBinding;
268	  };
269	  if (worktreePath) {
270	    const typedWorktree = workspacePaths.find((identity) => identity.matches(worktreePath));
271	    if (typedWorktree) typedPaths.push(typedWorktree);
272	    else {
273	      const findings = classifyPathComponents(worktreePath);
274	      if (findings.some((finding) => finding.classificationType !== "UNCERTAIN") || (findings.length > 0 && !bindingValidated())) {
275	        throw new Error("Task state worktree path has no selected workspace identity");
276	      }
277	    }
278	  }
279	  // A valid branch name is often long and varied enough to look high-entropy. One the repository confirms (Git lists
280	  // the worktree on it, and the registry or the task layout knows it) is an identity the next load needs verbatim:
281	  // redacting it would quarantine the record. Only uncertain findings qualify; a positive match is never preserved.
282	  const branch = value.worktreeBinding?.branch;
283	  let preserveBranch = false;
284	  if (typeof branch === "string") {
285	    const branchFindings = boundary.classifyText(branch);
286	    if (branchFindings.some((finding) => finding.classificationType !== "UNCERTAIN")) {
287	      throw new Error("Task state worktree branch contains positively classified sensitive material");
288	    }
289	    if (branchFindings.length > 0) {
290	      if (!bindingValidated()) throw new Error("Task state worktree branch has no validated worktree identity");
291	      preserveBranch = true;
292	    }
293	  }
294	  for (const identity of typedPaths) {
295	    const identityFindings = classifyPathComponents(identity.value);
296	    if (identityFindings.some((finding) => finding.classificationType !== "UNCERTAIN")) {
297	      throw new Error("Workspace identity contains positively classified sensitive material");
298	    }
299	  }
300	
301	  const preserveOperationGitPaths = hasValidatedOperationGitPaths(value as any, selectedWorkspace);
302	  const operationGit = (value as any).operation?.git;
303	  const maskWorktreePath = Boolean(worktreePath && (typedPaths.length > 1 || classifyPathComponents(worktreePath).length > 0));
304	  // Mask validated path fields before classification, then restore their exact values.
305	  const masked = {
306	    ...value,
307	    workspacePath: "[NEXUS_TYPED_WORKSPACE_PATH]",
308	    ...(value.workspace === undefined ? {} : { workspace: "[NEXUS_TYPED_WORKSPACE_PATH]" }),
309	    ...(maskWorktreePath || preserveBranch
310	      ? {
311	          worktreeBinding: {
312	            ...value.worktreeBinding,
313	            ...(maskWorktreePath ? { worktreePath: "[NEXUS_TYPED_WORKSPACE_PATH]" } : {}),
314	            ...(preserveBranch ? { branch: WORKTREE_BRANCH_PLACEHOLDER } : {}),
315	          },
316	        }
317	      : {}),
318	    ...(preserveOperationGitPaths ? {
319	      operation: {
320	        ...(value as any).operation,
321	        git: {
322	          ...operationGit,
323	          repoRoot: OPERATION_GIT_PATH_PLACEHOLDER,
324	          baseDir: OPERATION_GIT_PATH_PLACEHOLDER,
325	          integrationWorktree: OPERATION_GIT_PATH_PLACEHOLDER,
326	          units: Object.fromEntries(Object.entries(operationGit.units ?? {}).map(([id, unit]: [string, any]) => [
327	            id,
328	            { ...unit, worktree: OPERATION_GIT_PATH_PLACEHOLDER },
329	          ])),
330	        },
331	      },
332	    } : {}),
333	  };
334	  const protectedValue = redactForPersistence(masked);
335	  if (preserveOperationGitPaths &&
336	      Object.keys(operationGit.units ?? {}).length !== Object.keys(protectedValue.operation.git.units ?? {}).length) {
337	    throw new Error("Operation git unit identities collide during persistence protection");
338	  }
339	  return {
340	    ...protectedValue,
341	    workspacePath: selectedWorkspace.value,
342	    ...(value.workspace === undefined ? {} : { workspace: selectedWorkspace.value }),
343	    ...(maskWorktreePath || preserveBranch
344	      ? {
345	          worktreeBinding: {
346	            ...protectedValue.worktreeBinding,
347	            ...(maskWorktreePath ? { worktreePath } : {}),
348	            ...(preserveBranch ? { branch } : {}),
349	          },
350	        }
351	      : {}),
352	    ...(preserveOperationGitPaths ? {
353	      operation: {
354	        ...protectedValue.operation,
355	        git: {
356	          ...protectedValue.operation.git,
357	          repoRoot: operationGit.repoRoot,
358	          baseDir: operationGit.baseDir,
359	          integrationWorktree: operationGit.integrationWorktree,
360	          units: Object.fromEntries(Object.entries(protectedValue.operation.git.units ?? {}).map(([id, unit]: [string, any], index) => [
361	            id,
362	            { ...unit, worktree: (Object.values(operationGit.units ?? {})[index] as any).worktree },
363	          ])),
364	        },
365	      },
366	    } : {}),
367	  };
368	}
369	
370	/**
371	 * Refuse a durable copy when its source-of-truth content is positively classified
372	 * as sensitive. Checkpoint snapshots use this instead of creating a sanitized,
373	 * unrestorable workspace copy.
374	 *
375	 * Only positive findings (non-UNCERTAIN) block persistence. UNCERTAIN high-entropy
376	 * tokens are a low-confidence heuristic (DATA-004, confidence 0.55) that can
377	 * false-positive on ordinary long identifiers, so they are redacted where possible
378	 * but do not fail the checkpoint.
379	 */
380	export function assertNoSensitivePersistenceContent(value: unknown, destination: string): void {
381	  try {
382	    const text = typeof value === "string" ? value : JSON.stringify(value);
383	    if (text === undefined) return;
384	    const positive = InformationFlowBoundary.getGlobalInstance().classifyText(text);
385	    if (positive.some((finding) => finding.classificationType !== "UNCERTAIN")) {
386	      throw new SensitivePersistenceError(destination);
387	    }
388	  } catch (error) {
389	    if (error instanceof SensitivePersistenceError) throw error;
390	    throw new SensitivePersistenceError(destination);
391	  }
392	}
393	
394	export function appendProtectedHistoryLine(filePath: string, line: string): void {
395	  const safeLine = redactForPersistence(line);
396	  appendPrivateFile(filePath, `${safeLine}\n`);
397	}
398	
399	export function writeProtectedTextFile(filePath: string, content: string): void {
400	  const safeContent = redactForPersistence(content);
401	  try {
402	    writePrivateFile(filePath, safeContent, { durable: true });
403	  } catch {
404	    throw new Error("Protected persistence write failed");
405	  }
406	}
407	
408	export interface MiddlewareAuditRecord {
409	  kind: "middleware_rewrite";
410	  plugin: string;
411	  tool: string;
412	  phase: "pre" | "post";
413	  before_digest: string;
414	  after_digest: string;
415	  timestamp?: string;
416	  workspace?: string;
417	}
418	
419	export const DEFAULT_AUDIT_MAX_BYTES = 10 * 1024 * 1024; // 10 MB (REQ-PER-102, DEC-11)
420	export const DEFAULT_AUDIT_MAX_FILES = 5;
421	
422	export function getAuditMaxBytes(): number {
423	  const envVal = process.env.NEXUS_AUDIT_MAX_BYTES;
424	  if (envVal) {
425	    const parsed = parseInt(envVal, 10);
426	    if (!isNaN(parsed) && parsed > 0) return parsed;
427	  }
428	  return DEFAULT_AUDIT_MAX_BYTES;
429	}
430	
431	/**
432	 * Rotate audit.log when it exceeds maxBytes, keeping maxFiles backups (REQ-PER-102, ACC-PER-06).
433	 * Backups are audit.log.1 through audit.log.5, with permissions 0600.
434	 */
435	export function rotateAuditLogIfNeeded(
436	  auditPath: string,
437	  maxBytes: number = getAuditMaxBytes(),
438	  maxFiles: number = DEFAULT_AUDIT_MAX_FILES
439	): boolean {
440	  try {
441	    if (!fs.existsSync(auditPath)) return false;
442	    const stat = fs.statSync(auditPath);
443	    if (stat.size < maxBytes) return false;
444	
445	    for (let i = maxFiles; i >= 1; i--) {
446	      const src = i === 1 ? auditPath : `${auditPath}.${i - 1}`;
447	      const dest = `${auditPath}.${i}`;
448	      if (fs.existsSync(src)) {
449	        if (i === maxFiles && fs.existsSync(dest)) {
450	          try { fs.unlinkSync(dest); } catch {}
451	        }
452	        try {
453	          fs.renameSync(src, dest);
454	          try { fs.chmodSync(dest, 0o600); } catch {}
455	        } catch {}
456	      }
457	    }
458	    return true;
459	  } catch {
460	    return false;
461	  }
462	}
463	
464	/**
465	 * Record a middleware I/O rewrite audit record to ~/.nexus/audit.log (REQ-SEC-116, EXT-004, REQ-PER-102).
466	 */
467	export function recordMiddlewareAudit(record: MiddlewareAuditRecord): void {
468	  try {
469	    const auditDir = path.join(os.homedir(), ".nexus");
470	    ensurePrivateDir(auditDir);
471	    const auditPath = path.join(auditDir, "audit.log");
472	    rotateAuditLogIfNeeded(auditPath);
473	    const entry = {
474	      timestamp: record.timestamp || new Date().toISOString(),
475	      ...record,
476	    };
477	    // Middleware metadata can include operator-controlled workspace paths or plugin/tool names.
478	    // Apply the durable telemetry sanitizer to the entire record before the append boundary.
479	    const safeEntry = InformationFlowBoundary.getGlobalInstance().redactForTelemetry(entry);
480	    appendPrivateFile(auditPath, JSON.stringify(safeEntry) + "\n");
481	  } catch {
482	    // Ignore audit log write errors in restricted environments
483	  }
484	}
