/** Persist the operator's conversation restore in the operation event journal. */
export function recordCheckpointRestored(
  state: DurableOperationState,
  unitId: string,
  name: string,
  restored: { record: { messages: number }; backupDir?: string },
  now: () => number = Date.now,
): void {
  const at = now();
  const registry = new ResourceRegistry(state.resources, state.conditions, { now: () => at, random: Math.random });
  new ConvergenceScheduler(state, registry, () => at).emit(
    "CHECKPOINT_RESTORED",
    `Restored ${unitId} from checkpoint ${name} (${restored.record.messages} messages).`,
    { unitId, detail: { checkpoint: name, messages: restored.record.messages, ...(restored.backupDir ? { previousStateKept: restored.backupDir } : {}) } },
  );
  state.updatedAt = new Date(at).toISOString();
}

export interface OperationSpec {
  id?: string;
  objective: string;
  units: WorkUnitSpec[];
  resources?: Array<Partial<ResourceDescriptor> & { id: string; endpoint?: string; model: string }>;
  discoverCatalog?: boolean;
  policy?: Partial<OperationPolicy>;
  /** Opt-in Git isolation: each unit runs on its own worktree/branch; completions merge into an operation branch. */
  git?: { isolate?: boolean; baseRef?: string };
  /** SI-5: boundary rules the review gate enforces on each candidate diff (core/boundary_rules.ts). */
  boundaries?: BoundaryRules;
}

/**
 * An operation spec the operator must fix. Distinct from an internal failure: the CLI reports it as a usage error
 * (exit 2) and never starts work, so a typo cannot silently change what an operation does.
 */
export class OperationSpecError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "OperationSpecError";
  }
}

// The spec is untrusted operator input. Unknown keys are rejected rather than ignored: a silently ignored
// `git.publish` would leave the operator believing a PR will be opened, and a typo such as `depends` would drop a
// dependency and run work out of order.
const SPEC_KEYS = ["id", "objective", "units", "resources", "discoverCatalog", "policy", "git", "boundaries"] as const;
