// ---- The contract tables ----

test("the manual's verify exit-code table is the exported table", () => {
  const manual = fs.readFileSync(MANUAL, "utf8");
  const start = manual.indexOf("#### Exit codes of `nexus verify`");
  assert.ok(start >= 0, "the manual has the section");
  const rows = manual.slice(start).split("\n").slice(1);
  const first = rows.findIndex((line) => line.startsWith("|"));
  const table: string[] = [];
  for (let i = first; i < rows.length && rows[i].startsWith("|"); i++) table.push(rows[i]);
  const cells = table.map((line) => line.split("|").slice(1, -1).map((cell) => cell.trim()));
  assert.deepEqual(cells[0], ["Code", "Name", "When"]);
  assert.match(cells[1].join(""), /^[-: ]+$/);
  assert.deepEqual(
    cells.slice(2).map(([code, name, when]) => ({ code: Number(code), name: name.replace(/`/g, ""), when })),
    VERIFY_EXIT_CODES.map((row) => ({ ...row })),
  );
});

test("every reason has a verdict and an exit-code row; only VERIFIED exits 0", () => {
  assert.equal(new Set(VERIFY_EXIT_CODES.map((row) => row.name)).size, VERIFY_EXIT_CODES.length, "row names are unique");
  assert.deepEqual([...new Set(VERIFY_EXIT_CODES.map((row) => row.code))], [0, 1, 2, 3, 130]);
  assert.equal(verifyVerdictFor(undefined), "VERIFIED");
  assert.equal(verifyExitCode(verifyExitNameFor(undefined)), 0);
  for (const reason of Object.keys(VERIFY_REASONS) as VerifyReason[]) {
    const { verdict, exit } = VERIFY_REASONS[reason];
    assert.notEqual(verifyExitCode(exit), 0, reason);
    assert.equal(verifyExitCode(exit) === 3, verdict === "BLOCKED", `${reason}: exit 3 if and only if BLOCKED`);
    if (verdict === "REGRESSION_FREE") assert.equal(verifyExitCode(exit), 2, reason);
  }
    "manifest_root_mismatch",
    "manifest_sha256_mismatch",
    "signature_invalid",
    "signature_key_mismatch",
    "signature_missing",
    "unreadable_entry",
    "unsafe_entry",
    "unsupported_version",
  ]);
  assert.deepEqual(verifySchema.$defs.AuditSignatureStatus.enum, ["absent", "invalid", "missing", "unchecked", "valid"]);
  // Every result name is a row of the exit-code table.
  for (const name of verifySchema.$defs.AuditVerifyResultName.enum) assert.ok(AUDIT_EXIT_CODES.some((row) => row.name === name), name);

  const error: AuditVerifyError = { schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, error: "there is no bundle directory at that path", exitCode: 1 };
  assert.deepEqual(validate(error, verifySchema, verifySchema), []);
  assert.ok(validate({ ...error, schema_version: 2 }, verifySchema, verifySchema).length > 0);
  assert.ok(validate({ error: "x", exitCode: 1 }, verifySchema, verifySchema).length > 0, "a document without schema_version");
  assert.ok(validate({ schema_version: AUDIT_VERIFY_RESULT_SCHEMA_VERSION, result: "intact_unsigned" }, verifySchema, verifySchema).length > 0, "a result without its required members");
});

test("the exit-code table: only an export or an intact bundle is 0, and the signing rows are already there", () => {
  assert.deepEqual(
    AUDIT_EXIT_CODES.map((row) => [row.code, row.name]),
    [
      [0, "exported"],
      [0, "intact_signed"],
      [0, "intact_unsigned"],
      [1, "tampered"],
      [1, "error"],
      [1, "option_parse"],
      [2, "signature_unchecked"],
      [2, "unsupported_version"],
      [2, "usage"],
      [2, "subject_not_found"],
      [130, "interrupted"],
    ],
  );
  assert.equal(new Set(AUDIT_EXIT_CODES.map((row) => row.name)).size, AUDIT_EXIT_CODES.length, "each name is one row");
  for (const row of AUDIT_EXIT_CODES) {
    assert.deepEqual(Object.keys(row), ["code", "name", "when"], "the row shape of RUN_EXIT_CODES and VERIFY_EXIT_CODES");
    assert.ok(row.when.trim().length > 0);
    assert.equal(auditExitCode(row.name), row.code);
  }
  assert.deepEqual(Object.keys(RUN_EXIT_CODES[0]), ["code", "name", "when"]);
  assert.deepEqual(Object.keys(VERIFY_EXIT_CODES[0]), ["code", "name", "when"]);
  // The rows shared with the other commands keep their codes.
  for (const name of ["option_parse", "usage", "interrupted"] as const) {
    assert.equal(auditExitCode(name), RUN_EXIT_CODES.find((row) => row.name === name)!.code);
    assert.equal(auditExitCode(name), VERIFY_EXIT_CODES.find((row) => row.name === name)!.code);
  }
});
95:### `nexus verify`
96:`nexus verify` gives a verdict on a change that Nexus did not necessarily make: a pull request, a patch, another tool's output, your own edits. It uses no model. It runs the project's verifier on the code before the change and on the code after it, and applies the rules `nexus run` applies to its own work.
99:nexus verify --deliverable-file src/parser.ts                         # the working tree against HEAD
100:nexus verify --base origin/main --head my-branch --deliverable-file src/parser.ts   # one commit against another
101:nexus verify --base origin/main --verifier "npm test" --json --receipt verify.json
102:nexus verify --base origin/main --head my-branch -y --approve-verification-edit test/parser.test.ts   # after reading that edit
107:**Which verifier runs.** `--verifier <command>` is your own command (source `configured`) and needs no approval. Without it, one is discovered from the files of the **base** tree, never the head: the head is the change under test, so a head that rewrites `scripts.test` or adds a test script of its own does not get to choose the judge. A discovered verifier runs repository code, so it needs your approval: `nexus verify` stops with `BLOCKED` (exit code 3) and prints the command, the script it resolves to and a sha256 digest of both. Approve that exact verifier with `--approve-verifier <digest>`, or whatever is discovered with `--yes`. A base tree that defines no verifier gives `UNVERIFIED` (`NO_APPLICABLE_VERIFIER`). Each verifier run has a deadline (`--timeout-secs`, else `NEXUS_VERIFIER_TIMEOUT_SECS`, else 300 seconds); the type-checks of each side share one deadline of the same length.
118:#### Exit codes of `nexus verify`
123:| 1 | `error` | `UNVERIFIED` with reason `INTERNAL_ERROR`: `nexus verify` itself could not finish, so nothing was established. |
153:The guard's policy is the **base** tree's `.nexus-security.json` (`guard.policySource` is `base_tree`, or `default` when the base has none), read as an untrusted repository's: its `verificationPaths` can tighten the guard (`mode: "block"` refuses these edits even when you approve them; `extra` adds paths) and cannot relax it (`off`, `record` and `allow` are ignored). The head's `.nexus-security.json` is never read as policy; it is a finding. `nexus verify` does not consult your list of trusted workspaces, and `NEXUS_TRUST_WORKSPACE=1` does not change this (it is named in `environment` when set): trusting a checkout is not trusting the commit under review.
