298	/**
299	 * Stand-ins for the record's workspace and worktree paths while the loader and the redactor see it. The loader keeps a
300	 * path only when it is handed the workspace's live identity, which needs the directory to exist still and can run
301	 * `git` in it; without one it refuses a record whose path merely looks random, as most absolute paths do. The private
302	 * copy therefore carries these fixed strings, and the real paths are put back into the generated files afterwards.
303	 */
304	const WORKSPACE_STAND_IN = "[NEXUS_AUDIT_WORKSPACE]";
305	const WORKTREE_STAND_IN = "[NEXUS_AUDIT_WORKTREE]";
306	
307	/**
308	 * Runs the public loader and the session export on a private copy of the subject's files, so whatever the loader
309	 * repairs, migrates or quarantines happens there. No workspace identity is passed, so the loader never runs `git`.
310	 */
311	function loadFromPrivateCopy(snapshot: StoreSnapshot, id: string): LoadedSubject {
312	  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-audit-export-"));
313	  try {
314	    // One level down, so the loader's guard looks for its restore marker inside the scratch directory, not in the temp directory.
315	    const store = path.join(scratch, "store");
316	    fs.mkdirSync(store, { mode: 0o700 });
317	    const put = (name: string, bytes: Buffer | undefined): void => {
318	      if (bytes) fs.writeFileSync(path.join(store, name), bytes, { mode: 0o600, flag: "wx" });
319	    };
320	    const raw = snapshot.raw;
321	    const binding = raw.worktreeBinding;
322	    const copy = Buffer.from(
323	      JSON.stringify({
324	        ...raw,
325	        workspacePath: WORKSPACE_STAND_IN,
326	        workspace: WORKSPACE_STAND_IN,
327	        ...(isObject(binding) && typeof binding.worktreePath === "string" ? { worktreeBinding: { ...binding, worktreePath: WORKTREE_STAND_IN } } : {}),
328	      }),
329	      "utf8",
330	    );
331	    put(`${id}.json`, copy);
332	    put(`${id}.messages.jsonl`, snapshot.messages);
333	    const manager = new SessionManager(store);
334	    let state: DurableTaskState;
335	    try {
336	      state = manager.getStateManager().loadTaskState(id);
337	    } catch (err) {
338	      const message = (err instanceof Error ? err.message : String(err)).replaceAll(store, "<private copy>").replace(/ \(quarantined to [^)]*\)/, "");
339	      throw new AuditExportError("error", `the record of ${id} could not be loaded (${printable(message)}); nothing was exported and the store was left as it is`);
340	    }
341	    const reread = (name: string): Buffer | undefined => {
342	      try {
343	        return fs.readFileSync(path.join(store, name));
344	      } catch {
345	        return undefined;
346	      }
347	    };
348	    const rewritten = !reread(`${id}.json`)?.equals(copy) || (snapshot.messages !== undefined && !reread(`${id}.messages.jsonl`)?.equals(snapshot.messages));
