352	    // The session export reads the archive under the id the loaded record carries.
353	    if (auditIdProblem(session.id) === undefined) put(`${session.id}.history.jsonl`, snapshot.history);
354	    const exported = buildSessionExport(manager, session);
355	    return { session, exportJson: exported.json, exportMarkdown: exported.markdown, rewritten };
356	  } finally {
357	    fs.rmSync(scratch, { recursive: true, force: true });
358	  }
